   !> C interface of `azlcpo`: Return the azimuth/elevation coordinates of a specified target relative to an "observer," where the observer has constant position in a specified reference frame.
   integer(c_int) function c_pepper_azlcpo ( ctx, method, target, et, abcorr, azccw, elplsz, obspos, obsctr, obsref, &
         azlsta, lt ) bind(c, name='pepper_azlcpo')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: method(*)  !! Method to obtain the surface normal vector.
      character(kind=c_char), intent(in) :: target(*)  !! Name of target ephemeris object.
      real(c_double), value :: et  !! Observation epoch.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration correction.
      integer(c_int), value :: azccw  !! Flag indicating how azimuth is measured.
      integer(c_int), value :: elplsz  !! Flag indicating how elevation is measured.
      real(c_double), intent(in) :: obspos(3)  !! Observer position relative to center of motion.
      character(kind=c_char), intent(in) :: obsctr(*)  !! Center of motion of observer.
      character(kind=c_char), intent(in) :: obsref(*)  !! Body-fixed, body-centered frame of observer's center.
      real(c_double), intent(out) :: azlsta(6)  !! State of target with respect to observer, in azimuth/elevation coordinates.
      real(c_double), intent(out) :: lt  !! One way light time between target and observer.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_method
      character(:), allocatable :: f_target
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_obsctr
      character(:), allocatable :: f_obsref
      c_ => context_of(ctx)
      call c_to_f(method, f_method)
      call c_to_f(target, f_target)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(obsctr, f_obsctr)
      call c_to_f(obsref, f_obsref)
      call c_%azlcpo(f_method, f_target, et, f_abcorr, (azccw /= 0), (elplsz /= 0), obspos, f_obsctr, f_obsref, azlsta, lt)
      c_pepper_azlcpo = status_of(c_)
   end function c_pepper_azlcpo

