   integer(c_int) function c_pepper_cidfrm ( ctx, cent, frcode, frname_size, frname, found ) bind(c, &
         name='pepper_cidfrm')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: cent  !! an object to associate a frame with.
      integer(c_int), intent(out) :: frcode  !! the ID code of the frame associated with CENT
