      integer(c_int), intent(out) :: found  !! .TRUE. if the requested information is available.
      type(capi_context), pointer :: c_
      character(len=max(frname_size - 1, 1)) :: f_frname
      logical :: f_found
      c_ => context_of(ctx)
      f_frname = ' '
      call c_%cidfrm(cent, frcode, f_frname, f_found)
      call f_to_c(f_frname, frname_size, frname)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_cidfrm = status_of(c_)
   end function c_pepper_cidfrm

   !> C interface of `ck_coverage`: The coverage of an object in a CK file (PEPPER; [[ckcov]] without a window cell).
   integer(c_int) function c_pepper_ck_coverage ( ctx, file, inst, needav, level, tol, timsys, intervals, &
         intervals_rows, intervals_cols ) bind(c, name='pepper_ck_coverage')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the CK file
      integer(c_int), value :: inst  !! the ID code of the object (instrument or structure)
      integer(c_int), value :: needav  !! only the coverage with angular velocity
      character(kind=c_char), intent(in) :: level(*)  !! 'SEGMENT' or 'INTERVAL'
      real(c_double), value :: tol  !! the tolerance in ticks by which intervals are expanded
      character(kind=c_char), intent(in) :: timsys(*)  !! the time system of the result: 'TDB' or 'SCLK'
      type(c_ptr), intent(out) :: intervals  !! the coverage, shape (2, n) (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: intervals_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: intervals_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      character(:), allocatable :: f_level
      character(:), allocatable :: f_timsys
      real(wp), allocatable :: f_intervals(:,:)
      integer(c_int) :: intervals_total
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_to_f(level, f_level)
      call c_to_f(timsys, f_timsys)
      call c_%ck_coverage(f_file, inst, (needav /= 0), f_level, tol, f_timsys, f_intervals)
      if (.not. allocated(f_intervals)) allocate (f_intervals(0, 0))
      call set_real_result(c_, 1, reshape(f_intervals, [size(f_intervals)]), intervals, intervals_total)
      intervals_rows = int(size(f_intervals, 2), c_int)
      intervals_cols = int(size(f_intervals, 1), c_int)
      c_pepper_ck_coverage = status_of(c_)
   end function c_pepper_ck_coverage

   !> C interface of `ck_objects`: The objects of a CK file (PEPPER; [[ckobj]] without a set cell): their ID codes, sorted, without duplicates.
   integer(c_int) function c_pepper_ck_objects ( ctx, file, ids, ids_n ) bind(c, name='pepper_ck_objects')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the CK file
      type(c_ptr), intent(out) :: ids  !! the ID codes (size 0 after an error) (in the context)
      integer(c_int), intent(out) :: ids_n  !! its size
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      integer(ip), allocatable :: f_ids(:)
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_%ck_objects(f_file, f_ids)
      if (.not. allocated(f_ids)) allocate (f_ids(0))
      call set_int_result(c_, 1, f_ids, ids, ids_n)
      c_pepper_ck_objects = status_of(c_)
   end function c_pepper_ck_objects

