   !> C interface of `ckcov`: Find the coverage window for a specified object in a specified CK file.
   integer(c_int) function c_pepper_ckcov ( ctx, ckfnm, idcode, needav, level, tol, timsys, cover ) bind(c, &
         name='pepper_ckcov')
      type(c_ptr), value :: ctx  !! the context
