      character(kind=c_char), intent(in) :: level(*)  !! Coverage level: 'SEGMENT' OR 'INTERVAL'.
      real(c_double), value :: tol  !! Tolerance in ticks.
      character(kind=c_char), intent(in) :: timsys(*)  !! Time system used to represent coverage.
      real(c_double), intent(inout) :: cover(-5:*)  !! Window giving coverage for IDCODE. (a cell: the control area first)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_ckfnm
      character(:), allocatable :: f_level
      character(:), allocatable :: f_timsys
      c_ => context_of(ctx)
      call c_to_f(ckfnm, f_ckfnm)
      call c_to_f(level, f_level)
      call c_to_f(timsys, f_timsys)
      call c_%ckcov(f_ckfnm, idcode, (needav /= 0), f_level, tol, f_timsys, cover)
      c_pepper_ckcov = status_of(c_)
   end function c_pepper_ckcov

