   !> C interface of `ckpfs`: Evaluate pointing data from a segment for a given time.
   integer(c_int) function c_pepper_ckpfs ( ctx, handle, descr, sclkdp, tol, needav, cmat, av, clkout, &
         found ) bind(c, name='pepper_ckpfs')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! CK file handle.
      real(c_double), intent(in) :: descr(*)  !! Segment descriptor.
      real(c_double), value :: sclkdp  !! Spacecraft clock time.
      real(c_double), value :: tol  !! Time tolerance.
      integer(c_int), value :: needav  !! .TRUE. when angular velocity data is requested.
      real(c_double), intent(out) :: cmat(3,3)  !! C-matrix.
      real(c_double), intent(out) :: av(3)  !! Angular velocity vector.
      real(c_double), intent(out) :: clkout  !! Output spacecraft clock time.
      integer(c_int), intent(out) :: found  !! .TRUE. when requested pointing is available.
      type(capi_context), pointer :: c_
      logical :: f_found
      c_ => context_of(ctx)
      call c_%ckpfs(handle, descr, sclkdp, tol, (needav /= 0), cmat, av, clkout, f_found)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_ckpfs = status_of(c_)
   end function c_pepper_ckpfs

