      integer(c_int), intent(in) :: degres(*)  !! Array of polynomial degrees of mini-segments.
      real(c_double), intent(in) :: packts(*)  !! Array of data packets of mini-segments.
      real(c_double), intent(in) :: rates(*)  !! Nominal SCLK rates in seconds per tick.
      real(c_double), intent(in) :: sclkdp(*)  !! Array of epochs of mini-segments.
      real(c_double), intent(in) :: ivlbds(*)  !! Mini-segment interval bounds.
