      c_ => context_of(ctx)
      call c_to_f(ref, f_ref)
      call c_to_f(segid, f_segid)
      call c_%ckw06(handle, inst, f_ref, (avflag /= 0), first, last, f_segid, nmini, npkts, subtps, degres, packts, rates, &
               sclkdp, ivlbds, (sellst /= 0))
      c_pepper_ckw06 = status_of(c_)
