   !> C interface of `cnmfrm`: Retrieve frame ID code and name to associate with an object.
   integer(c_int) function c_pepper_cnmfrm ( ctx, cname, frcode, frname_size, frname, found ) bind(c, &
         name='pepper_cnmfrm')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: cname(*)  !! name of the object to find a frame for
      integer(c_int), intent(out) :: frcode  !! the ID code of the frame associated with CNAME
      integer(c_int), value :: frname_size  !! the size of frname (with the NUL)
      character(kind=c_char), intent(out) :: frname(*)  !! the name of the frame with ID FRCODE
      integer(c_int), intent(out) :: found  !! .TRUE. if the requested information is available.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_cname
      character(len=max(frname_size - 1, 1)) :: f_frname
      logical :: f_found
      c_ => context_of(ctx)
      call c_to_f(cname, f_cname)
      f_frname = ' '
      call c_%cnmfrm(f_cname, frcode, f_frname, f_found)
      call f_to_c(f_frname, frname_size, frname)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_cnmfrm = status_of(c_)
   end function c_pepper_cnmfrm

