         name='pepper_dasadc')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! DAS file handle.
      integer(c_int), value :: n  !! Number of characters to add to file.
      integer(c_int), value :: bpos  !! Begin and end positions of substrings.
      integer(c_int), value :: epos  !! Begin and end positions of substrings.
      integer(c_int), value :: data_n  !! the number of strings in data
      integer(c_int), value :: data_width  !! the width of each string in data
