   !> C interface of `dasrfr`: Return the contents of the file record of a specified DAS file.
   integer(c_int) function c_pepper_dasrfr ( ctx, handle, idword_size, idword, ifname_size, ifname, nresvr, nresvc, &
         ncomr, ncomc ) bind(c, name='pepper_dasrfr')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! DAS file handle.
      integer(c_int), value :: idword_size  !! the size of idword (with the NUL)
      character(kind=c_char), intent(out) :: idword(*)  !! ID word.
      integer(c_int), value :: ifname_size  !! the size of ifname (with the NUL)
      character(kind=c_char), intent(out) :: ifname(*)  !! DAS internal file name.
      integer(c_int), intent(out) :: nresvr  !! Number of reserved records in file.
      integer(c_int), intent(out) :: nresvc  !! Number of characters in use in reserved rec. area.
      integer(c_int), intent(out) :: ncomr  !! Number of comment records in file.
      integer(c_int), intent(out) :: ncomc  !! Number of characters in use in comment area.
      type(capi_context), pointer :: c_
      character(len=max(idword_size - 1, 1)) :: f_idword
      character(len=max(ifname_size - 1, 1)) :: f_ifname
      c_ => context_of(ctx)
      f_idword = ' '
      f_ifname = ' '
      call c_%dasrfr(handle, f_idword, f_ifname, nresvr, nresvc, ncomr, ncomc)
      call f_to_c(f_idword, idword_size, idword)
      call f_to_c(f_ifname, ifname_size, ifname)
      c_pepper_dasrfr = status_of(c_)
   end function c_pepper_dasrfr

   !> C interface of `dasrrc`: Read DAS character physical records.
   integer(c_int) function c_pepper_dasrrc ( ctx, handle, recno, first, last, datac_size, datac ) bind(c, &
         name='pepper_dasrrc')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! Handle of DAS file.
      integer(c_int), value :: recno  !! Record number.
      integer(c_int), value :: first  !! First and last indices of range within record.
      integer(c_int), value :: last  !! First and last indices of range within record.
      integer(c_int), value :: datac_size  !! the size of datac (with the NUL)
      character(kind=c_char), intent(out) :: datac(*)  !! Character data read from record.
      type(capi_context), pointer :: c_
      character(len=max(datac_size - 1, 1)) :: f_datac
      c_ => context_of(ctx)
      f_datac = ' '
      call c_%dasrrc(handle, recno, first, last, f_datac)
      call f_to_c(f_datac, datac_size, datac)
      c_pepper_dasrrc = status_of(c_)
   end function c_pepper_dasrrc

