   !> C interface of `dnearp`: Compute the state (position and velocity) of an ellipsoid surface point nearest to the position component of a specified state.
   integer(c_int) function c_pepper_dnearp ( ctx, state, a, b, c, dnear, dalt, found ) bind(c, name='pepper_dnearp')
      type(c_ptr), value :: ctx  !! the context
