   !> C interface of `dp2hx`: Convert a double precision number to an equivalent character string using a base 16 "scientific notation."  ## Detailed Input  NUMBER   is the double precision number to be converted to a character string representation.
   integer(c_int) function c_pepper_dp2hx ( ctx, number, hxstr_size, hxstr, hxssiz ) bind(c, name='pepper_dp2hx')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), value :: number  !! D.p. number to be converted.
      integer(c_int), value :: hxstr_size  !! the size of hxstr (with the NUL)
      character(kind=c_char), intent(out) :: hxstr(*)  !! Equivalent character string, left justified.
      integer(c_int), intent(out) :: hxssiz  !! Length of the character string produced.
      type(capi_context), pointer :: c_
      character(len=max(hxstr_size - 1, 1)) :: f_hxstr
      c_ => context_of(ctx)
      f_hxstr = ' '
      call c_%dp2hx(number, f_hxstr, hxssiz)
      call f_to_c(f_hxstr, hxstr_size, hxstr)
      c_pepper_dp2hx = status_of(c_)
   end function c_pepper_dp2hx

   !> C interface of `dpfmt`: Create a formatted string that represents a double precision number, using a format picture.
   integer(c_int) function c_pepper_dpfmt ( ctx, x, pictur, str_size, str ) bind(c, name='pepper_dpfmt')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), value :: x  !! a double precision number.
      character(kind=c_char), intent(in) :: pictur(*)  !! a string describing the appearance of the output
      integer(c_int), value :: str_size  !! the size of str (with the NUL)
      character(kind=c_char), intent(out) :: str(*)  !! a string representing X as prescribed by PICTUR
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_pictur
      character(len=max(str_size - 1, 1)) :: f_str
      c_ => context_of(ctx)
      call c_to_f(pictur, f_pictur)
      f_str = ' '
      call c_%dpfmt(x, f_pictur, f_str)
      call f_to_c(f_str, str_size, str)
      c_pepper_dpfmt = status_of(c_)
   end function c_pepper_dpfmt

