   !> C interface of `dsk_objects`: The bodies of a DSK file (PEPPER; [[dskobj]] without a set cell): their ID codes, sorted, without duplicates.
   integer(c_int) function c_pepper_dsk_objects ( ctx, file, ids, ids_n ) bind(c, name='pepper_dsk_objects')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the DSK file
      type(c_ptr), intent(out) :: ids  !! the body ID codes (size 0 after an error) (in the context)
      integer(c_int), intent(out) :: ids_n  !! its size
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      integer(ip), allocatable :: f_ids(:)
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_%dsk_objects(f_file, f_ids)
      if (.not. allocated(f_ids)) allocate (f_ids(0))
      call set_int_result(c_, 1, f_ids, ids, ids_n)
      c_pepper_dsk_objects = status_of(c_)
   end function c_pepper_dsk_objects

   !> C interface of `dsk_plates`: All the plates of a type 2 DSK segment (PEPPER; [[dskp02]] with the size from [[dskz02]]).
   integer(c_int) function c_pepper_dsk_plates ( ctx, handle, dladsc, plates, plates_rows, plates_cols ) bind(c, &
         name='pepper_dsk_plates')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! the handle of the DSK file
      integer(c_int), intent(in) :: dladsc(*)  !! the DLA descriptor of the segment
      type(c_ptr), intent(out) :: plates  !! the plates, shape (3, n): vertex indices (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: plates_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: plates_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      integer(ip), allocatable :: f_plates(:,:)
      integer(c_int) :: plates_total
      c_ => context_of(ctx)
      call c_%dsk_plates(handle, dladsc, f_plates)
      if (.not. allocated(f_plates)) allocate (f_plates(0, 0))
      call set_int_result(c_, 1, reshape(f_plates, [size(f_plates)]), plates, plates_total)
      plates_rows = int(size(f_plates, 2), c_int)
      plates_cols = int(size(f_plates, 1), c_int)
      c_pepper_dsk_plates = status_of(c_)
   end function c_pepper_dsk_plates

