   !> C interface of `dtpool`: Return the data about a kernel pool variable.
   integer(c_int) function c_pepper_dtpool ( ctx, name, found, n, type_size, type ) bind(c, name='pepper_dtpool')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: name(*)  !! Name of the variable whose value is to be returned.
      integer(c_int), intent(out) :: found  !! .TRUE. if variable is in pool.
      integer(c_int), intent(out) :: n  !! Number of values returned for NAME.
      integer(c_int), value :: type_size  !! the size of type (with the NUL)
      character(kind=c_char), intent(out) :: type(*)  !! Type of the variable 'C', 'N', 'X'
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_name
      logical :: f_found
      character(len=max(type_size - 1, 1)) :: f_type
      c_ => context_of(ctx)
      call c_to_f(name, f_name)
      f_type = ' '
      call c_%dtpool(f_name, f_found, n, f_type)
      found = merge(1_c_int, 0_c_int, f_found)
      call f_to_c(f_type, type_size, type)
      c_pepper_dtpool = status_of(c_)
   end function c_pepper_dtpool

