   !> C interface of `ekgc`: Return an element of an entry in a column of character type in a specified row.
   integer(c_int) function c_pepper_ekgc ( ctx, selidx, row, elment, cdata_size, cdata, null, found ) bind(c, &
         name='pepper_ekgc')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: selidx  !! Index of parent column in SELECT clause.
      integer(c_int), value :: row  !! Row to fetch from.
      integer(c_int), value :: elment  !! Index of element, within column entry, to fetch.
      integer(c_int), value :: cdata_size  !! the size of cdata (with the NUL)
      character(kind=c_char), intent(out) :: cdata(*)  !! Character string element of column entry.
      integer(c_int), intent(out) :: null  !! Flag indicating whether column entry was null.
      integer(c_int), intent(out) :: found  !! Flag indicating whether column was present in row.
      type(capi_context), pointer :: c_
      character(len=max(cdata_size - 1, 1)) :: f_cdata
      logical :: f_null
      logical :: f_found
      c_ => context_of(ctx)
      f_cdata = ' '
      call c_%ekgc(selidx, row, elment, f_cdata, f_null, f_found)
      call f_to_c(f_cdata, cdata_size, cdata)
      null = merge(1_c_int, 0_c_int, f_null)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_ekgc = status_of(c_)
   end function c_pepper_ekgc

   !> C interface of `ekgd`: Return an element of an entry in a column of double precision or `time' type in a specified row.
   integer(c_int) function c_pepper_ekgd ( ctx, selidx, row, elment, ddata, null, found ) bind(c, name='pepper_ekgd')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: selidx  !! Index of parent column in SELECT clause.
      integer(c_int), value :: row  !! Row to fetch from.
      integer(c_int), value :: elment  !! Index of element, within column entry, to fetch.
      real(c_double), intent(out) :: ddata  !! D.p. element of column entry.
      integer(c_int), intent(out) :: null  !! Flag indicating whether column entry was null.
      integer(c_int), intent(out) :: found  !! Flag indicating whether column was present in row.
      type(capi_context), pointer :: c_
      logical :: f_null
      logical :: f_found
      c_ => context_of(ctx)
      call c_%ekgd(selidx, row, elment, ddata, f_null, f_found)
