      call c_to_f_array(cnames, cnames_n, cnames_width, f_cnames)
      call c_to_f_array(decls, decls_n, decls_width, f_decls)
      call c_%ekifld(handle, f_tabnam, ncols, nrows, f_cnames, f_decls, segno, rcptrs)
