   !> C interface of `et2lst`: Compute the local solar time for a given ephemeris epoch ET for an object on the surface of a body at a specified longitude.
   integer(c_int) function c_pepper_et2lst ( ctx, et, body, lon, type, hr, mn, sc, time_size, time, ampm_size, &
         ampm ) bind(c, name='pepper_et2lst')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), value :: et  !! Epoch in seconds past J2000 epoch
      integer(c_int), value :: body  !! ID-code of the body of interest
      real(c_double), value :: lon  !! Longitude of surface point (RADIANS)
      character(kind=c_char), intent(in) :: type(*)  !! Type of longitude 'PLANETOCENTRIC', etc.
      integer(c_int), intent(out) :: hr  !! Local hour on a "24 hour" clock
      integer(c_int), intent(out) :: mn  !! Minutes past the hour
      integer(c_int), intent(out) :: sc  !! Seconds past the minute
      integer(c_int), value :: time_size  !! the size of time (with the NUL)
      character(kind=c_char), intent(out) :: time(*)  !! String giving local time on 24 hour clock
      integer(c_int), value :: ampm_size  !! the size of ampm (with the NUL)
      character(kind=c_char), intent(out) :: ampm(*)  !! String giving time on A.M./ P.M. scale
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_type
      character(len=max(time_size - 1, 1)) :: f_time
      character(len=max(ampm_size - 1, 1)) :: f_ampm
      c_ => context_of(ctx)
      call c_to_f(type, f_type)
      f_time = ' '
      f_ampm = ' '
      call c_%et2lst(et, body, lon, f_type, hr, mn, sc, f_time, f_ampm)
      call f_to_c(f_time, time_size, time)
      call f_to_c(f_ampm, ampm_size, ampm)
      c_pepper_et2lst = status_of(c_)
   end function c_pepper_et2lst

