   !> C interface of `fov_by_code`: The field of view of an instrument given by its ID code, with all its boundary vectors and a frame name of any length (PEPPER; [[getfov]] with the size taken from the pool).
   integer(c_int) function c_pepper_fov_by_code ( ctx, instid, shape, shape_len, frame, frame_len, bsight, bounds, &
         bounds_rows, bounds_cols ) bind(c, name='pepper_fov_by_code')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: instid  !! the NAIF ID code of the instrument
      type(c_ptr), intent(out) :: shape  !! the FOV shape: CIRCLE, ELLIPSE, POLYGON or RECTANGLE (in the context)
      integer(c_int), intent(out) :: shape_len  !! its length
      type(c_ptr), intent(out) :: frame  !! the frame of the vectors (in the context)
      integer(c_int), intent(out) :: frame_len  !! its length
      real(c_double), intent(out) :: bsight(3)  !! the boresight vector
      type(c_ptr), intent(out) :: bounds  !! the boundary vectors, shape (3, n) (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: bounds_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: bounds_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_shape
      character(:), allocatable :: f_frame
      real(wp), allocatable :: f_bounds(:,:)
      integer(c_int) :: bounds_total
      c_ => context_of(ctx)
      call c_%fov_by_code(instid, f_shape, f_frame, bsight, f_bounds)
      if (.not. allocated(f_shape)) f_shape = ''
      call set_string_result(c_, 1, f_shape, shape, shape_len)
      if (.not. allocated(f_frame)) f_frame = ''
      call set_string_result(c_, 2, f_frame, frame, frame_len)
      if (.not. allocated(f_bounds)) allocate (f_bounds(0, 0))
      call set_real_result(c_, 1, reshape(f_bounds, [size(f_bounds)]), bounds, bounds_total)
      bounds_rows = int(size(f_bounds, 2), c_int)
      bounds_cols = int(size(f_bounds, 1), c_int)
      c_pepper_fov_by_code = status_of(c_)
   end function c_pepper_fov_by_code

   !> C interface of `fov_by_name`: The field of view of an instrument given by name, with all its boundary vectors and a frame name of any length (PEPPER; [[getfvn]] with the size taken from the pool).
   integer(c_int) function c_pepper_fov_by_name ( ctx, inst, shape, shape_len, frame, frame_len, bsight, bounds, &
         bounds_rows, bounds_cols ) bind(c, name='pepper_fov_by_name')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: inst(*)  !! the name of the instrument
      type(c_ptr), intent(out) :: shape  !! the FOV shape: CIRCLE, ELLIPSE, POLYGON or RECTANGLE (in the context)
      integer(c_int), intent(out) :: shape_len  !! its length
      type(c_ptr), intent(out) :: frame  !! the frame of the vectors (in the context)
      integer(c_int), intent(out) :: frame_len  !! its length
      real(c_double), intent(out) :: bsight(3)  !! the boresight vector
      type(c_ptr), intent(out) :: bounds  !! the boundary vectors, shape (3, n) (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: bounds_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: bounds_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_inst
      character(:), allocatable :: f_shape
      character(:), allocatable :: f_frame
      real(wp), allocatable :: f_bounds(:,:)
      integer(c_int) :: bounds_total
      c_ => context_of(ctx)
      call c_to_f(inst, f_inst)
      call c_%fov_by_name(f_inst, f_shape, f_frame, bsight, f_bounds)
      if (.not. allocated(f_shape)) f_shape = ''
      call set_string_result(c_, 1, f_shape, shape, shape_len)
      if (.not. allocated(f_frame)) f_frame = ''
      call set_string_result(c_, 2, f_frame, frame, frame_len)
      if (.not. allocated(f_bounds)) allocate (f_bounds(0, 0))
      call set_real_result(c_, 1, reshape(f_bounds, [size(f_bounds)]), bounds, bounds_total)
      bounds_rows = int(size(f_bounds, 2), c_int)
      bounds_cols = int(size(f_bounds, 1), c_int)
      c_pepper_fov_by_name = status_of(c_)
   end function c_pepper_fov_by_name

