   !> C interface of `frame_name`: The name of a frame from its ID code, of any length (PEPPER; the body of [[frmnam]], which truncates to its argument's length).
   integer(c_int) function c_pepper_frame_name ( ctx, frcode, frname, frname_len, found ) bind(c, &
         name='pepper_frame_name')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: frcode  !! the frame ID code
      type(c_ptr), intent(out) :: frname  !! the frame name (empty if not found) (in the context)
      integer(c_int), intent(out) :: frname_len  !! its length
      integer(c_int), intent(out) :: found  !! the frame is known
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_frname
      logical :: f_found
      c_ => context_of(ctx)
      call c_%frame_name(frcode, f_frname, f_found)
      if (.not. allocated(f_frname)) f_frname = ''
      call set_string_result(c_, 1, f_frname, frname, frname_len)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_frame_name = status_of(c_)
   end function c_pepper_frame_name

   !> C interface of `frinfo`: Retrieve the minimal attributes associated with a frame needed for converting transformations to and from it.
   integer(c_int) function c_pepper_frinfo ( ctx, frcode, cent, frclss, clssid, found ) bind(c, name='pepper_frinfo')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: frcode  !! the ID code for some frame
      integer(c_int), intent(out) :: cent  !! the center of the frame
      integer(c_int), intent(out) :: frclss  !! the class (type) of the frame
      integer(c_int), intent(out) :: clssid  !! the ID code for the frame within its class.
      integer(c_int), intent(out) :: found  !! .TRUE. if the requested information is available.
      type(capi_context), pointer :: c_
      logical :: f_found
      c_ => context_of(ctx)
      call c_%frinfo(frcode, cent, frclss, clssid, f_found)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_frinfo = status_of(c_)
   end function c_pepper_frinfo

   !> C interface of `frmchg`: Return the state transformation matrix from one frame to another.
   integer(c_int) function c_pepper_frmchg ( ctx, frame1, frame2, et, xform ) bind(c, name='pepper_frmchg')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: frame1  !! the frame id-code for some reference frame
      integer(c_int), value :: frame2  !! the frame id-code for some reference frame
      real(c_double), value :: et  !! an epoch in TDB seconds past J2000.
      real(c_double), intent(out) :: xform(6,6)  !! a state transformation matrix
      type(capi_context), pointer :: c_
      c_ => context_of(ctx)
      call c_%frmchg(frame1, frame2, et, xform)
      c_pepper_frmchg = status_of(c_)
   end function c_pepper_frmchg

   !> C interface of `frmget`: Find the transformation from a user specified frame to another frame at a user specified epoch.
   integer(c_int) function c_pepper_frmget ( ctx, infrm, et, xform, outfrm, found ) bind(c, name='pepper_frmget')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: infrm  !! The integer code for a SPICE reference frame.
      real(c_double), value :: et  !! An epoch in seconds past J2000.
      real(c_double), intent(out) :: xform(6,6)  !! A state transformation matrix.
      integer(c_int), intent(out) :: outfrm  !! The frame that XFORM transforms INFRM to.
      integer(c_int), intent(out) :: found  !! .TRUE. if a frame transformation can be found.
      type(capi_context), pointer :: c_
      logical :: f_found
      c_ => context_of(ctx)
      call c_%frmget(infrm, et, xform, outfrm, f_found)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_frmget = status_of(c_)
   end function c_pepper_frmget

   !> C interface of `frmnam`: Retrieve the name of a reference frame associated with a SPICE ID code.
   integer(c_int) function c_pepper_frmnam ( ctx, frcode, frname_size, frname ) bind(c, name='pepper_frmnam')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: frcode  !! an integer code for a reference frame
      integer(c_int), value :: frname_size  !! the size of frname (with the NUL)
      character(kind=c_char), intent(out) :: frname(*)  !! the name associated with the reference frame.
      type(capi_context), pointer :: c_
      character(len=max(frname_size - 1, 1)) :: f_frname
      c_ => context_of(ctx)
      f_frname = ' '
      call c_%frmnam(frcode, f_frname)
      call f_to_c(f_frname, frname_size, frname)
      c_pepper_frmnam = status_of(c_)
   end function c_pepper_frmnam

   !> C interface of `georec`: Convert geodetic coordinates to rectangular coordinates.
   integer(c_int) function c_pepper_georec ( ctx, lon, lat, alt, re, f, rectan ) bind(c, name='pepper_georec')
      type(c_ptr), value :: ctx  !! the context
