   !> C interface of `gf_intercept`: A GF search on a coordinate of a surface intercept vector (PEPPER; [[gfsntc]] with the confinement and result windows as arrays, and without workspace).
   integer(c_int) function c_pepper_gf_intercept ( ctx, target, fixref, method, abcorr, obsrvr, dref, dvec, crdsys, &
