   !> C interface of `hx2dp`: Convert a string representing a double precision number in a base 16 "scientific notation" into its equivalent double precision number.
   integer(c_int) function c_pepper_hx2dp ( ctx, string, number, error, errmsg_size, errmsg ) bind(c, &
         name='pepper_hx2dp')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: string(*)  !! Hex form string to convert to double precision.
      real(c_double), intent(out) :: number  !! Double precision value to be returned.
      integer(c_int), intent(out) :: error  !! A logical flag which is .TRUE. on error.
      integer(c_int), value :: errmsg_size  !! the size of errmsg (with the NUL)
      character(kind=c_char), intent(out) :: errmsg(*)  !! A descriptive error message.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_string
      logical :: f_error
      character(len=max(errmsg_size - 1, 1)) :: f_errmsg
      c_ => context_of(ctx)
      call c_to_f(string, f_string)
      f_errmsg = ' '
      call c_%hx2dp(f_string, number, f_error, f_errmsg)
      error = merge(1_c_int, 0_c_int, f_error)
      call f_to_c(f_errmsg, errmsg_size, errmsg)
      c_pepper_hx2dp = status_of(c_)
   end function c_pepper_hx2dp

