   integer(c_int) function c_pepper_hyptof ( ctx, ma, ecc, f ) bind(c, name='pepper_hyptof')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), value :: ma  !! Mean anomaly at epoch.
      real(c_double), value :: ecc  !! Eccentricity.
      real(c_double), intent(out) :: f  !! Hyperbolic eccentric anomaly.
      type(capi_context), pointer :: c_
      c_ => context_of(ctx)
      call c_%hyptof(ma, ecc, f)
      c_pepper_hyptof = status_of(c_)
   end function c_pepper_hyptof

   !> C interface of `idw2at`: Extract the architecture and type of a SPICE binary kernel file from a file ID word.
   integer(c_int) function c_pepper_idw2at ( ctx, idword, arch_size, arch, type_size, type ) bind(c, &
         name='pepper_idw2at')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: idword(*)  !! The IDWORD to be examined.
      integer(c_int), value :: arch_size  !! the size of arch (with the NUL)
      character(kind=c_char), intent(out) :: arch(*)  !! The file architecture DAS or DAF.
      integer(c_int), value :: type_size  !! the size of type (with the NUL)
      character(kind=c_char), intent(out) :: type(*)  !! The type of the file.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_idword
      character(len=max(arch_size - 1, 1)) :: f_arch
      character(len=max(type_size - 1, 1)) :: f_type
      c_ => context_of(ctx)
      call c_to_f(idword, f_idword)
      f_arch = ' '
      f_type = ' '
      call c_%idw2at(f_idword, f_arch, f_type)
      call f_to_c(f_arch, arch_size, arch)
      call f_to_c(f_type, type_size, type)
      c_pepper_idw2at = status_of(c_)
   end function c_pepper_idw2at

