   !> C interface of `illumf`: Compute the illumination angles---phase, incidence, and emission---at a specified point on a target body.
   integer(c_int) function c_pepper_illumf ( ctx, method, target, ilusrc, et, fixref, abcorr, obsrvr, spoint, trgepc, &
         srfvec, phase, incdnc, emissn, visibl, lit ) bind(c, name='pepper_illumf')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: method(*)  !! Computation method.
      character(kind=c_char), intent(in) :: target(*)  !! Name of target body.
      character(kind=c_char), intent(in) :: ilusrc(*)  !! Name of illumination source.
      real(c_double), value :: et  !! Epoch in ephemeris seconds past J2000 TDB.
      character(kind=c_char), intent(in) :: fixref(*)  !! Body-fixed, body-centered target body frame.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Desired aberration correction.
      character(kind=c_char), intent(in) :: obsrvr(*)  !! Name of observing body.
      real(c_double), intent(in) :: spoint(3)  !! Body-fixed coordinates of a target surface point.
      real(c_double), intent(out) :: trgepc  !! Target surface point epoch.
      real(c_double), intent(out) :: srfvec(3)  !! Vector from observer to target surface point.
      real(c_double), intent(out) :: phase  !! Phase angle at the surface point.
      real(c_double), intent(out) :: incdnc  !! Source incidence angle at the surface point.
      real(c_double), intent(out) :: emissn  !! Emission angle at the surface point.
      integer(c_int), intent(out) :: visibl  !! Visibility flag (.TRUE. = visible).
      integer(c_int), intent(out) :: lit  !! Illumination flag (.TRUE. = illuminated).
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_method
      character(:), allocatable :: f_target
      character(:), allocatable :: f_ilusrc
      character(:), allocatable :: f_fixref
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_obsrvr
      logical :: f_visibl
      logical :: f_lit
      c_ => context_of(ctx)
      call c_to_f(method, f_method)
      call c_to_f(target, f_target)
      call c_to_f(ilusrc, f_ilusrc)
      call c_to_f(fixref, f_fixref)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(obsrvr, f_obsrvr)
      call c_%illumf(f_method, f_target, f_ilusrc, et, f_fixref, f_abcorr, f_obsrvr, spoint, trgepc, srfvec, phase, incdnc, &
               emissn, f_visibl, f_lit)
      visibl = merge(1_c_int, 0_c_int, f_visibl)
      lit = merge(1_c_int, 0_c_int, f_lit)
      c_pepper_illumf = status_of(c_)
   end function c_pepper_illumf

