   !> C interface of `kdata`: Return data for the nth kernel that is among a list of specified kernel types.
   integer(c_int) function c_pepper_kdata ( ctx, which, kind, file_size, file, filtyp_size, filtyp, srcfil_size, &
         srcfil, handle, found ) bind(c, name='pepper_kdata')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: which  !! Index of kernel to fetch from the list of kernels.
      character(kind=c_char), intent(in) :: kind(*)  !! The kind of kernel to which fetches are limited.
      integer(c_int), value :: file_size  !! the size of file (with the NUL)
      character(kind=c_char), intent(out) :: file(*)  !! The name of the kernel file.
      integer(c_int), value :: filtyp_size  !! the size of filtyp (with the NUL)
      character(kind=c_char), intent(out) :: filtyp(*)  !! The type of the kernel.
      integer(c_int), value :: srcfil_size  !! the size of srcfil (with the NUL)
      character(kind=c_char), intent(out) :: srcfil(*)  !! Name of the source file used to load FILE.
      integer(c_int), intent(out) :: handle  !! The handle attached to FILE.
      integer(c_int), intent(out) :: found  !! .TRUE. if the specified file could be located.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_kind
      character(len=max(file_size - 1, 1)) :: f_file
      character(len=max(filtyp_size - 1, 1)) :: f_filtyp
      character(len=max(srcfil_size - 1, 1)) :: f_srcfil
      logical :: f_found
      c_ => context_of(ctx)
      call c_to_f(kind, f_kind)
      f_file = ' '
      f_filtyp = ' '
      f_srcfil = ' '
      call c_%kdata(which, f_kind, f_file, f_filtyp, f_srcfil, handle, f_found)
      call f_to_c(f_file, file_size, file)
      call f_to_c(f_filtyp, filtyp_size, filtyp)
      call f_to_c(f_srcfil, srcfil_size, srcfil)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_kdata = status_of(c_)
   end function c_pepper_kdata

