   !> C interface of `kernel_data`: The data of the nth kernel of a kind loaded through FURNSH, with file names of any length (PEPPER; [[kdata]], which truncates to its arguments' lengths).
   integer(c_int) function c_pepper_kernel_data ( ctx, which, kind, file, file_len, filtyp, filtyp_len, source, &
         source_len, handle, found ) bind(c, name='pepper_kernel_data')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: which  !! the index of the kernel among those of KIND
      character(kind=c_char), intent(in) :: kind(*)  !! the kinds of kernel ('ALL', 'SPK', 'CK TEXT', ..., as [[kdata]])
      type(c_ptr), intent(out) :: file  !! the file name (empty if not found) (in the context)
      integer(c_int), intent(out) :: file_len  !! its length
      type(c_ptr), intent(out) :: filtyp  !! the kernel type: SPK, CK, PCK, DSK, EK, TEXT or META (in the context)
      integer(c_int), intent(out) :: filtyp_len  !! its length
      type(c_ptr), intent(out) :: source  !! the meta-kernel it was loaded from (empty if loaded directly) (in the context)
      integer(c_int), intent(out) :: source_len  !! its length
      integer(c_int), intent(out) :: handle  !! its handle (0 for a text or meta-kernel)
      integer(c_int), intent(out) :: found  !! a kernel was found
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_kind
      character(:), allocatable :: f_file
      character(:), allocatable :: f_filtyp
      character(:), allocatable :: f_source
      logical :: f_found
      c_ => context_of(ctx)
      call c_to_f(kind, f_kind)
      call c_%kernel_data(which, f_kind, f_file, f_filtyp, f_source, handle, f_found)
      if (.not. allocated(f_file)) f_file = ''
      call set_string_result(c_, 1, f_file, file, file_len)
      if (.not. allocated(f_filtyp)) f_filtyp = ''
      call set_string_result(c_, 2, f_filtyp, filtyp, filtyp_len)
      if (.not. allocated(f_source)) f_source = ''
      call set_string_result(c_, 3, f_source, source, source_len)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_kernel_data = status_of(c_)
   end function c_pepper_kernel_data

   !> C interface of `kernel_format`: The loader and the description of a loaded kernel (PEPPER): for a file read by a kernel loader, the loader's name and the builder's description; for a programmatic kernel, a blank loader and its description (`(programmatic)` if none was set); for SPICE's own kernels, blanks.
   integer(c_int) function c_pepper_kernel_format ( ctx, file, loader, loader_len, format, format_len, &
         found ) bind(c, name='pepper_kernel_format')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the kernel (as loaded)
      type(c_ptr), intent(out) :: loader  !! the loader's name (blank if none) (in the context)
      integer(c_int), intent(out) :: loader_len  !! its length
      type(c_ptr), intent(out) :: format  !! the description (blank if none) (in the context)
      integer(c_int), intent(out) :: format_len  !! its length
      integer(c_int), intent(out) :: found  !! a kernel has this name
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      character(:), allocatable :: f_loader
      character(:), allocatable :: f_format
      logical :: f_found
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_%kernel_format(f_file, f_loader, f_format, f_found)
      if (.not. allocated(f_loader)) f_loader = ''
      call set_string_result(c_, 1, f_loader, loader, loader_len)
      if (.not. allocated(f_format)) f_format = ''
      call set_string_result(c_, 2, f_format, format, format_len)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_kernel_format = status_of(c_)
   end function c_pepper_kernel_format

