      integer(c_int), value :: n  !! Number of points defining the polynomial.
      type(c_ptr), value :: ctx  !! the context
      real(c_double), intent(in) :: xvals(n)  !! Abscissa values.
      real(c_double), intent(in) :: yvals(n)  !! Ordinate values.
      real(c_double), intent(inout) :: work(*)  !! workspace
      real(c_double), value :: x  !! Point at which to interpolate the polynomial.
      real(c_double), intent(out) :: p  !! Polynomial value at X.
      real(c_double), intent(out) :: dp  !! Polynomial derivative at X.
      type(capi_context), pointer :: c_
      c_ => context_of(ctx)
      call c_%lgrind(n, xvals, yvals, work, x, p, dp)
      c_pepper_lgrind = status_of(c_)
   end function c_pepper_lgrind

   !> C interface of `lgrint`: Evaluate a Lagrange interpolating polynomial for a specified set of coordinate pairs, at a specified abscissa value.
   integer(c_int) function c_pepper_lgrint ( ctx, n, xvals, yvals, work, x, fresult ) bind(c, name='pepper_lgrint')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: n  !! Number of points defining the polynomial.
      real(c_double), intent(in) :: xvals(*)  !! Abscissa values.
      real(c_double), intent(in) :: yvals(*)  !! Ordinate values.
      real(c_double), intent(inout) :: work(*)  !! workspace
      real(c_double), value :: x  !! Point at which to interpolate the polynomial.
      real(c_double), intent(out) :: fresult  !! the result
      type(capi_context), pointer :: c_
      real(wp) :: f_fresult
      c_ => context_of(ctx)
      f_fresult = c_%lgrint(n, xvals, yvals, work, x)
      fresult = f_fresult
      c_pepper_lgrint = status_of(c_)
   end function c_pepper_lgrint

   !> C interface of `limb_points`: Limb points on a target body, without a limit on their number (PEPPER; [[limbpt]] without MAXN).
   integer(c_int) function c_pepper_limb_points ( ctx, method, target, et, fixref, abcorr, corloc, obsrvr, refvec, &
         rolstp, ncuts, schstp, soltol, npts, npts_n, points, points_rows, points_cols, epochs, epochs_n, tangts, &
         tangts_rows, tangts_cols ) bind(c, name='pepper_limb_points')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: method(*)  !! the computation method, as for [[limbpt]]
      character(kind=c_char), intent(in) :: target(*)  !! the name of the target body
      real(c_double), value :: et  !! the epoch (TDB seconds past J2000)
      character(kind=c_char), intent(in) :: fixref(*)  !! the body-fixed, body-centered target body frame
      character(kind=c_char), intent(in) :: abcorr(*)  !! the aberration correction
      character(kind=c_char), intent(in) :: corloc(*)  !! the aberration correction locus
      character(kind=c_char), intent(in) :: obsrvr(*)  !! the name of the observing body
      real(c_double), intent(in) :: refvec(3)  !! the reference vector for the cutting half-planes
      real(c_double), value :: rolstp  !! the roll angular step between the cutting half-planes
      integer(c_int), value :: ncuts  !! the number of cutting half-planes
      real(c_double), value :: schstp  !! the angular step size for searching (DSK shapes)
      real(c_double), value :: soltol  !! the solution convergence tolerance (DSK shapes)
      type(c_ptr), intent(out) :: npts  !! the number of points of each cut (size 0 after an error) (in the context)
      integer(c_int), intent(out) :: npts_n  !! its size
      type(c_ptr), intent(out) :: points  !! the limb points, shape (3, n) (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: points_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: points_cols  !! its number of columns (Fortran: rows)
      type(c_ptr), intent(out) :: epochs  !! the epochs of the points (in the context)
      integer(c_int), intent(out) :: epochs_n  !! its size
      type(c_ptr), intent(out) :: tangts  !! the tangent vectors from the observer to the points, shape (3, n) (in the context)
      integer(c_int), intent(out) :: tangts_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: tangts_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_method
      character(:), allocatable :: f_target
      character(:), allocatable :: f_fixref
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_corloc
      character(:), allocatable :: f_obsrvr
      integer(ip), allocatable :: f_npts(:)
      real(wp), allocatable :: f_points(:,:)
      integer(c_int) :: points_total
      real(wp), allocatable :: f_epochs(:)
      real(wp), allocatable :: f_tangts(:,:)
      integer(c_int) :: tangts_total
      c_ => context_of(ctx)
      call c_to_f(method, f_method)
      call c_to_f(target, f_target)
      call c_to_f(fixref, f_fixref)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(corloc, f_corloc)
      call c_to_f(obsrvr, f_obsrvr)
      call c_%limb_points(f_method, f_target, et, f_fixref, f_abcorr, f_corloc, f_obsrvr, refvec, rolstp, ncuts, schstp, &
               soltol, f_npts, f_points, f_epochs, f_tangts)
      if (.not. allocated(f_npts)) allocate (f_npts(0))
      call set_int_result(c_, 1, f_npts, npts, npts_n)
      if (.not. allocated(f_points)) allocate (f_points(0, 0))
      call set_real_result(c_, 1, reshape(f_points, [size(f_points)]), points, points_total)
      points_rows = int(size(f_points, 2), c_int)
      points_cols = int(size(f_points, 1), c_int)
      if (.not. allocated(f_epochs)) allocate (f_epochs(0))
      call set_real_result(c_, 2, f_epochs, epochs, epochs_n)
      if (.not. allocated(f_tangts)) allocate (f_tangts(0, 0))
      call set_real_result(c_, 3, reshape(f_tangts, [size(f_tangts)]), tangts, tangts_total)
      tangts_rows = int(size(f_tangts, 2), c_int)
      tangts_cols = int(size(f_tangts, 1), c_int)
      c_pepper_limb_points = status_of(c_)
   end function c_pepper_limb_points

   !> C interface of `loader_names`: The names of the kernel loaders registered on the context's instance ([[spice_add_loader]]), in the order of registration (PEPPER).
   integer(c_int) function c_pepper_loader_names ( ctx, names, names_n ) bind(c, name='pepper_loader_names')
      type(c_ptr), value :: ctx  !! the context
      type(c_ptr), intent(out) :: names  !! the loaders' names (upper case) (in the context, each NUL-terminated)
      integer(c_int), intent(out) :: names_n  !! the number of strings
      type(capi_context), pointer :: c_
      type(string), allocatable :: f_names(:)
      c_ => context_of(ctx)
      call c_%loader_names(f_names)
      if (.not. allocated(f_names)) allocate (f_names(0))
      call set_strings_result(c_, 1, f_names, names, names_n)
      c_pepper_loader_names = status_of(c_)
   end function c_pepper_loader_names

   !> C interface of `locln`: Locate a group of lines in a text file delimited by markers.
   integer(c_int) function c_pepper_locln ( ctx, unit, bmark, emark, line_size, line, bline, eline, found ) bind(c, &
         name='pepper_locln')
      integer(c_int), value :: line_size  !! the size of line (with the NUL)
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: unit  !! Logical unit connected to text file.
      character(kind=c_char), intent(in) :: bmark(*)  !! Begin marker.
      character(kind=c_char), intent(in) :: emark(*)  !! End marker.
      character(kind=c_char), intent(inout) :: line(line_size)  !! Workspace.
      integer(c_int), intent(out) :: bline  !! Beginning line.
      integer(c_int), intent(out) :: eline  !! Ending line.
      integer(c_int), intent(out) :: found  !! Markers found?
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_bmark
      character(:), allocatable :: f_emark
      character(len=max(line_size - 1, 1)) :: f_line
      character(:), allocatable :: t_line
      logical :: f_found
      c_ => context_of(ctx)
      call c_to_f(bmark, f_bmark)
      call c_to_f(emark, f_emark)
      call c_to_f(line, t_line)
      f_line = t_line
      call c_%locln(unit, f_bmark, f_emark, f_line, bline, eline, f_found)
      call f_to_c(f_line, line_size, line)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_locln = status_of(c_)
   end function c_pepper_locln

