   !> C interface of `npsgpt`: Find the nearest point on a line segment to a given point.
   integer(c_int) function c_pepper_npsgpt ( ctx, ep1, ep2, point, pnear, dist ) bind(c, name='pepper_npsgpt')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), intent(in) :: ep1(3)  !! Endpoints of a line segment.
      real(c_double), intent(in) :: ep2(3)  !! Endpoints of a line segment.
      real(c_double), intent(in) :: point(3)  !! A point in 3-dimensional space.
      real(c_double), intent(out) :: pnear(3)  !! Nearest point on the line segment to POINT.
      real(c_double), intent(out) :: dist  !! Distance between PNEAR and POINT.
      type(capi_context), pointer :: c_
      c_ => context_of(ctx)
      call c_%npsgpt(ep1, ep2, point, pnear, dist)
      c_pepper_npsgpt = status_of(c_)
   end function c_pepper_npsgpt

