   !> C interface of `occult`: Determine the occultation condition (not occulted, partially occulted, etc.) of one target relative to another target as seen by an observer at a given time.
   integer(c_int) function c_pepper_occult ( ctx, targ1, shape1, frame1, targ2, shape2, frame2, abcorr, obsrvr, et, &
         ocltid ) bind(c, name='pepper_occult')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: targ1(*)  !! Name or ID of first target.
      character(kind=c_char), intent(in) :: shape1(*)  !! Type of shape model used for first target.
      character(kind=c_char), intent(in) :: frame1(*)  !! Body-fixed, body-centered frame for first body.
      character(kind=c_char), intent(in) :: targ2(*)  !! Name or ID of second target.
      character(kind=c_char), intent(in) :: shape2(*)  !! Type of shape model used for second target.
      character(kind=c_char), intent(in) :: frame2(*)  !! Body-fixed, body-centered frame for second body.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration correction flag.
      character(kind=c_char), intent(in) :: obsrvr(*)  !! Name or ID of the observer.
      real(c_double), value :: et  !! Time of the observation (seconds past J2000).
      integer(c_int), intent(out) :: ocltid  !! Occultation identification code.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_targ1
      character(:), allocatable :: f_shape1
      character(:), allocatable :: f_frame1
      character(:), allocatable :: f_targ2
      character(:), allocatable :: f_shape2
      character(:), allocatable :: f_frame2
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_obsrvr
      c_ => context_of(ctx)
      call c_to_f(targ1, f_targ1)
      call c_to_f(shape1, f_shape1)
      call c_to_f(frame1, f_frame1)
      call c_to_f(targ2, f_targ2)
      call c_to_f(shape2, f_shape2)
      call c_to_f(frame2, f_frame2)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(obsrvr, f_obsrvr)
      call c_%occult(f_targ1, f_shape1, f_frame1, f_targ2, f_shape2, f_frame2, f_abcorr, f_obsrvr, et, ocltid)
      c_pepper_occult = status_of(c_)
   end function c_pepper_occult

