   !> C interface of `pck_coverage`: The coverage of a frame in a binary PCK file (PEPPER; [[pckcov]] without a window cell).
   integer(c_int) function c_pepper_pck_coverage ( ctx, file, frame, intervals, intervals_rows, &
         intervals_cols ) bind(c, name='pepper_pck_coverage')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the binary PCK file
      integer(c_int), value :: frame  !! the frame class ID code
      type(c_ptr), intent(out) :: intervals  !! the coverage, shape (2, n) (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: intervals_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: intervals_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      real(wp), allocatable :: f_intervals(:,:)
      integer(c_int) :: intervals_total
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_%pck_coverage(f_file, frame, f_intervals)
      if (.not. allocated(f_intervals)) allocate (f_intervals(0, 0))
      call set_real_result(c_, 1, reshape(f_intervals, [size(f_intervals)]), intervals, intervals_total)
      intervals_rows = int(size(f_intervals, 2), c_int)
      intervals_cols = int(size(f_intervals, 1), c_int)
      c_pepper_pck_coverage = status_of(c_)
   end function c_pepper_pck_coverage

   !> C interface of `pck_frames`: The frames of a binary PCK file (PEPPER; [[pckfrm]] without a set cell): their class ID codes, sorted, without duplicates.
   integer(c_int) function c_pepper_pck_frames ( ctx, file, ids, ids_n ) bind(c, name='pepper_pck_frames')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the binary PCK file
      type(c_ptr), intent(out) :: ids  !! the frame class ID codes (size 0 after an error) (in the context)
      integer(c_int), intent(out) :: ids_n  !! its size
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      integer(ip), allocatable :: f_ids(:)
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_%pck_frames(f_file, f_ids)
      if (.not. allocated(f_ids)) allocate (f_ids(0))
      call set_int_result(c_, 1, f_ids, ids, ids_n)
      c_pepper_pck_frames = status_of(c_)
   end function c_pepper_pck_frames

