   !> C interface of `pckeul`: This routine is obsolete.
   integer(c_int) function c_pepper_pckeul ( ctx, body, et, found, ref_size, ref, eulang ) bind(c, name='pepper_pckeul')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: body  !! ID code of body
      real(c_double), value :: et  !! Epoch of transformation
      integer(c_int), intent(out) :: found  !! .TRUE. if ET, BODY found in a PCK file
      integer(c_int), value :: ref_size  !! the size of ref (with the NUL)
      character(kind=c_char), intent(out) :: ref(*)  !! Name of inertial ref. frame of state
      real(c_double), intent(out) :: eulang(6)  !! Euler angles and their derivatives.
      type(capi_context), pointer :: c_
      logical :: f_found
      character(len=max(ref_size - 1, 1)) :: f_ref
      c_ => context_of(ctx)
      f_ref = ' '
      call c_%pckeul(body, et, f_found, f_ref, eulang)
      found = merge(1_c_int, 0_c_int, f_found)
      call f_to_c(f_ref, ref_size, ref)
      c_pepper_pckeul = status_of(c_)
   end function c_pepper_pckeul

