   !> C interface of `pckw02`: Write a type 2 segment to a PCK binary file given the file handle, body-fixed frame class ID, frame, time range covered by the segment, and the Chebyshev polynomial coefficients.
   integer(c_int) function c_pepper_pckw02 ( ctx, handle, clssid, frame, first, last, segid, intlen, n, polydg, &
         cdata, btime ) bind(c, name='pepper_pckw02')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! Handle of binary PCK file open for writing.
      integer(c_int), value :: clssid  !! Frame class ID of body-fixed frame.
      character(kind=c_char), intent(in) :: frame(*)  !! Reference frame name.
      real(c_double), value :: first  !! Start time of interval covered by segment.
      real(c_double), value :: last  !! End time of interval covered by segment.
      character(kind=c_char), intent(in) :: segid(*)  !! Segment identifier.
      real(c_double), value :: intlen  !! Length of time covered by logical record.
      integer(c_int), value :: n  !! Number of logical records in segment.
      integer(c_int), value :: polydg  !! Chebyshev polynomial degree.
      real(c_double), intent(in) :: cdata(*)  !! Array of Chebyshev coefficients.
      real(c_double), value :: btime  !! Begin time of first logical record.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_frame
      character(:), allocatable :: f_segid
      c_ => context_of(ctx)
      call c_to_f(frame, f_frame)
      call c_to_f(segid, f_segid)
      call c_%pckw02(handle, clssid, f_frame, first, last, f_segid, intlen, n, polydg, cdata, btime)
      c_pepper_pckw02 = status_of(c_)
   end function c_pepper_pckw02

   !> C interface of `pckw20`: Write a type 20 segment to a PCK file.
   integer(c_int) function c_pepper_pckw20 ( ctx, handle, clssid, frame, first, last, segid, intlen, n, polydg, &
         cdata, ascale, tscale, initjd, initfr ) bind(c, name='pepper_pckw20')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! Handle of PCK file open for writing.
      integer(c_int), value :: clssid  !! NAIF PCK frame class ID.
      character(kind=c_char), intent(in) :: frame(*)  !! Reference frame name.
      real(c_double), value :: first  !! Start time of interval covered by segment.
      real(c_double), value :: last  !! End time of interval covered by segment.
      character(kind=c_char), intent(in) :: segid(*)  !! Segment identifier.
      real(c_double), value :: intlen  !! Length of time covered by logical record (days).
      integer(c_int), value :: n  !! Number of logical records in segment.
      integer(c_int), value :: polydg  !! Chebyshev polynomial degree.
      real(c_double), intent(in) :: cdata(*)  !! Array of Chebyshev coefficients and angles.
      real(c_double), value :: ascale  !! Angular scale of data.
      real(c_double), value :: tscale  !! Time scale of data.
      real(c_double), value :: initjd  !! Integer part of begin time (TDB Julian date) of first record.
      real(c_double), value :: initfr  !! Fractional part of begin time (TDB Julian date) of first record.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_frame
      character(:), allocatable :: f_segid
      c_ => context_of(ctx)
      call c_to_f(frame, f_frame)
      call c_to_f(segid, f_segid)
      call c_%pckw20(handle, clssid, f_frame, first, last, f_segid, intlen, n, polydg, cdata, ascale, tscale, initjd, initfr)
      c_pepper_pckw20 = status_of(c_)
   end function c_pepper_pckw20

