      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: dspmsg(*)  !! The prompt to use when asking for input.
      integer(c_int), value :: buffer_size  !! the size of buffer (with the NUL)
      character(kind=c_char), intent(out) :: buffer(*)  !! The response typed by a user.
