      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: from(*)  !! Name of the frame to transform from.
      character(kind=c_char), intent(in) :: to(*)  !! Name of the frame to transform to.
      real(c_double), value :: et  !! Epoch of the rotation matrix.
      real(c_double), intent(out) :: rotate(3,3)  !! A rotation matrix.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_from
      character(:), allocatable :: f_to
      c_ => context_of(ctx)
      call c_to_f(from, f_from)
      call c_to_f(to, f_to)
      call c_%pxform(f_from, f_to, et, rotate)
      c_pepper_pxform = status_of(c_)
   end function c_pepper_pxform

