   !> C interface of `rdkdat`: Read the next line of data from a SPICE ASCII kernel file.
   integer(c_int) function c_pepper_rdkdat ( ctx, line_size, line, eof ) bind(c, name='pepper_rdkdat')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: line_size  !! the size of line (with the NUL)
      character(kind=c_char), intent(out) :: line(*)  !! Next line of kernel data.
      integer(c_int), intent(out) :: eof  !! End of file indicator.
      type(capi_context), pointer :: c_
      character(len=max(line_size - 1, 1)) :: f_line
      logical :: f_eof
      c_ => context_of(ctx)
      f_line = ' '
      call c_%rdkdat(f_line, f_eof)
      call f_to_c(f_line, line_size, line)
      eof = merge(1_c_int, 0_c_int, f_eof)
      c_pepper_rdkdat = status_of(c_)
   end function c_pepper_rdkdat

