   integer(c_int) function c_pepper_repsub ( ctx, in, left, right, string, out_size, out ) bind(c, name='pepper_repsub')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: in(*)  !! Input string.
      integer(c_int), value :: left  !! Ends of substring to be replaced.
      integer(c_int), value :: right  !! Ends of substring to be replaced.
      character(kind=c_char), intent(in) :: string(*)  !! Replacement string.
      integer(c_int), value :: out_size  !! the size of out (with the NUL)
      character(kind=c_char), intent(out) :: out(*)  !! Resulting string.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_in
      character(:), allocatable :: f_string
      character(len=max(out_size - 1, 1)) :: f_out
      c_ => context_of(ctx)
      call c_to_f(in, f_in)
      call c_to_f(string, f_string)
      f_out = ' '
      call c_%repsub(f_in, left, right, f_string, f_out)
      call f_to_c(f_out, out_size, out)
      c_pepper_repsub = status_of(c_)
   end function c_pepper_repsub

