      real(c_double), value :: sclkdp  !! Type 1 SCLK, encoded as ticks since clock start.
      real(c_double), intent(out) :: et  !! Ephemeris time, seconds past J2000. (PEPPER: an output; SPICELIB's table said I)
      type(capi_context), pointer :: c_
      c_ => context_of(ctx)
      call c_%scte01(sc, sclkdp, et)
      c_pepper_scte01 = status_of(c_)
   end function c_pepper_scte01

