   !> C interface of `sepool`: Retrieve the string starting at the FIDX element of the kernel pool variable, where the string may be continued across several components of the kernel pool variable.
   integer(c_int) function c_pepper_sepool ( ctx, item, fidx, contin, string_size, string, size, lidx, &
         found ) bind(c, name='pepper_sepool')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: item(*)  !! name of the kernel pool variable
      integer(c_int), value :: fidx  !! index of the first component of the string
      character(kind=c_char), intent(in) :: contin(*)  !! character sequence used to indicate continuation
      integer(c_int), value :: string_size  !! the size of string (with the NUL)
      character(kind=c_char), intent(out) :: string(*)  !! a full string concatenated across continuations
      integer(c_int), intent(out) :: size  !! the number of character in the full string value
      integer(c_int), intent(out) :: lidx  !! index of the last component of the string
      integer(c_int), intent(out) :: found  !! flag indicating success or failure of request
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_item
      character(:), allocatable :: f_contin
      character(len=max(string_size - 1, 1)) :: f_string
      logical :: f_found
      c_ => context_of(ctx)
      call c_to_f(item, f_item)
      call c_to_f(contin, f_contin)
      f_string = ' '
      call c_%sepool(f_item, fidx, f_contin, f_string, size, lidx, f_found)
      call f_to_c(f_string, string_size, string)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_sepool = status_of(c_)
   end function c_pepper_sepool

