   !> C interface of `shiftc`: Shift the contents of a character string to the left or right.
   integer(c_int) function c_pepper_shiftc ( ctx, in, dir, nshift, fillc, out_size, out ) bind(c, name='pepper_shiftc')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: in(*)  !! Input string.
      character(kind=c_char), intent(in) :: dir(*)  !! Direction to shift.
      integer(c_int), value :: nshift  !! Number of times to shift.
      character(kind=c_char), intent(in) :: fillc(*)  !! Character to fill spaces left vacant.
      integer(c_int), value :: out_size  !! the size of out (with the NUL)
      character(kind=c_char), intent(out) :: out(*)  !! Shifted string.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_in
      character(:), allocatable :: f_dir
      character(:), allocatable :: f_fillc
      character(len=max(out_size - 1, 1)) :: f_out
      c_ => context_of(ctx)
      call c_to_f(in, f_in)
      call c_to_f(dir, f_dir)
      call c_to_f(fillc, f_fillc)
      f_out = ' '
      call c_%shiftc(f_in, f_dir, nshift, f_fillc, f_out)
      call f_to_c(f_out, out_size, out)
      c_pepper_shiftc = status_of(c_)
   end function c_pepper_shiftc

   !> C interface of `sincpt`: Compute, for a given observer and a ray emanating from the observer, the surface intercept of the ray on a target body at a specified epoch, optionally corrected for light time and stellar aberration.
   integer(c_int) function c_pepper_sincpt ( ctx, method, target, et, fixref, abcorr, obsrvr, dref, dvec, spoint, &
         trgepc, srfvec, found ) bind(c, name='pepper_sincpt')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: method(*)  !! Computation method.
      character(kind=c_char), intent(in) :: target(*)  !! Name of target body.
      real(c_double), value :: et  !! Epoch in ephemeris seconds past J2000 TDB.
      character(kind=c_char), intent(in) :: fixref(*)  !! Body-fixed, body-centered target body frame.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration correction.
      character(kind=c_char), intent(in) :: obsrvr(*)  !! Name of observing body.
      character(kind=c_char), intent(in) :: dref(*)  !! Reference frame of ray's direction vector.
      real(c_double), intent(in) :: dvec(3)  !! Ray's direction vector.
      real(c_double), intent(out) :: spoint(3)  !! Surface intercept point on the target body.
      real(c_double), intent(out) :: trgepc  !! Intercept epoch.
      real(c_double), intent(out) :: srfvec(3)  !! Vector from observer to intercept point.
      integer(c_int), intent(out) :: found  !! Flag indicating whether intercept was found.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_method
      character(:), allocatable :: f_target
      character(:), allocatable :: f_fixref
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_obsrvr
      character(:), allocatable :: f_dref
      logical :: f_found
      c_ => context_of(ctx)
      call c_to_f(method, f_method)
      call c_to_f(target, f_target)
      call c_to_f(fixref, f_fixref)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(obsrvr, f_obsrvr)
      call c_to_f(dref, f_dref)
      call c_%sincpt(f_method, f_target, et, f_fixref, f_abcorr, f_obsrvr, f_dref, dvec, spoint, trgepc, srfvec, f_found)
      found = merge(1_c_int, 0_c_int, f_found)
      c_pepper_sincpt = status_of(c_)
   end function c_pepper_sincpt

