      c_ => context_of(ctx)
      call c_%spcdc(handle)
      c_pepper_spcdc = status_of(c_)
   end function c_pepper_spcdc

   !> C interface of `spcec`: Extract the text from the comment area of a binary SPK or CK file and write it to a text file.
   integer(c_int) function c_pepper_spcec ( ctx, handle, unit ) bind(c, name='pepper_spcec')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! Handle assigned to binary SPK or CK file.
      integer(c_int), value :: unit  !! Logical unit connected to text file.
      type(capi_context), pointer :: c_
      c_ => context_of(ctx)
      call c_%spcec(handle, unit)
      c_pepper_spcec = status_of(c_)
   end function c_pepper_spcec

   !> C interface of `spcopn`: Open a new SPK or CK file for subsequent write requests.
   integer(c_int) function c_pepper_spcopn ( ctx, fname, ifname, handle ) bind(c, name='pepper_spcopn')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: fname(*)  !! Name of SPK or CK file to be created.
      character(kind=c_char), intent(in) :: ifname(*)  !! Internal file name.
      integer(c_int), intent(out) :: handle  !! Handle of new SPK or CK file.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_fname
      character(:), allocatable :: f_ifname
      c_ => context_of(ctx)
      call c_to_f(fname, f_fname)
      call c_to_f(ifname, f_ifname)
      call c_%spcopn(f_fname, f_ifname, handle)
      c_pepper_spcopn = status_of(c_)
   end function c_pepper_spcopn

   !> C interface of `spcrfl`: Read the first line of text from the comment area of a binary SPK or CK file.
   integer(c_int) function c_pepper_spcrfl ( ctx, handle, line_size, line, eoc ) bind(c, name='pepper_spcrfl')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! Handle assigned to binary SPK or CK file.
      integer(c_int), value :: line_size  !! the size of line (with the NUL)
      character(kind=c_char), intent(out) :: line(*)  !! First line of text from the comment area.
      integer(c_int), intent(out) :: eoc  !! End of comments?
      type(capi_context), pointer :: c_
      character(len=max(line_size - 1, 1)) :: f_line
      logical :: f_eoc
      c_ => context_of(ctx)
      f_line = ' '
      call c_%spcrfl(handle, f_line, f_eoc)
      call f_to_c(f_line, line_size, line)
      eoc = merge(1_c_int, 0_c_int, f_eoc)
      c_pepper_spcrfl = status_of(c_)
   end function c_pepper_spcrfl

   !> C interface of `spcrnl`: Continue reading lines from the comment area of a binary SPK or CK file specified by the most recent call to the routine [[spcrfl]].
   integer(c_int) function c_pepper_spcrnl ( ctx, line_size, line, eoc ) bind(c, name='pepper_spcrnl')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: line_size  !! the size of line (with the NUL)
      character(kind=c_char), intent(out) :: line(*)  !! Next line of text from the comment area.
      integer(c_int), intent(out) :: eoc  !! End of comments?
      type(capi_context), pointer :: c_
      character(len=max(line_size - 1, 1)) :: f_line
      logical :: f_eoc
      c_ => context_of(ctx)
      f_line = ' '
      call c_%spcrnl(f_line, f_eoc)
      call f_to_c(f_line, line_size, line)
      eoc = merge(1_c_int, 0_c_int, f_eoc)
      c_pepper_spcrnl = status_of(c_)
   end function c_pepper_spcrnl

   !> C interface of `spct2b`: Reconstruct a binary SPK or CK file including comments from a text file opened by the calling program.
   integer(c_int) function c_pepper_spct2b ( ctx, unit, binary ) bind(c, name='pepper_spct2b')
      type(c_ptr), value :: ctx  !! the context
