   !> C interface of `sphsd`: Return the distance between two points on a sphere, measured along the shortest great circle arc connecting them.
   integer(c_int) function c_pepper_sphsd ( ctx, radius, lon1, lat1, lon2, lat2, fresult ) bind(c, name='pepper_sphsd')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), value :: radius  !! Radius of sphere.
      real(c_double), value :: lon1  !! Longitude and latitude of first point in radians.
      real(c_double), value :: lat1  !! Longitude and latitude of first point in radians.
      real(c_double), value :: lon2  !! Longitude and latitude of second point in radians.
      real(c_double), value :: lat2  !! Longitude and latitude of second point in radians.
      real(c_double), intent(out) :: fresult  !! the result
      type(capi_context), pointer :: c_
      real(wp) :: f_fresult
      c_ => context_of(ctx)
      f_fresult = c_%sphsd(radius, lon1, lat1, lon2, lat2)
      fresult = f_fresult
      c_pepper_sphsd = status_of(c_)
   end function c_pepper_sphsd

   !> C interface of `spk14a`: Add data to a type 14 SPK segment associated with HANDLE.
   integer(c_int) function c_pepper_spk14a ( ctx, handle, ncsets, coeffs, epochs ) bind(c, name='pepper_spk14a')
      type(c_ptr), value :: ctx  !! the context
