   !> C interface of `spk14b`: Begin a type 14 SPK segment in the SPK file associated with HANDLE.
   integer(c_int) function c_pepper_spk14b ( ctx, handle, segid, body, center, frame, first, last, chbdeg ) bind(c, &
         name='pepper_spk14b')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! The handle of an SPK file open for writing.
      character(kind=c_char), intent(in) :: segid(*)  !! The string to use for segment identifier.
      integer(c_int), value :: body  !! The NAIF ID code for the body of the segment.
      integer(c_int), value :: center  !! The center of motion for BODY.
      character(kind=c_char), intent(in) :: frame(*)  !! The reference frame for this segment.
      real(c_double), value :: first  !! The first epoch for which the segment is valid.
      real(c_double), value :: last  !! The last epoch for which the segment is valid.
      integer(c_int), value :: chbdeg  !! The degree of the Chebyshev Polynomial used.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_segid
      character(:), allocatable :: f_frame
      c_ => context_of(ctx)
      call c_to_f(segid, f_segid)
      call c_to_f(frame, f_frame)
      call c_%spk14b(handle, f_segid, body, center, f_frame, first, last, chbdeg)
      c_pepper_spk14b = status_of(c_)
   end function c_pepper_spk14b

   !> C interface of `spk14e`: End the type 14 SPK segment currently being written to the SPK file associated with HANDLE.
   integer(c_int) function c_pepper_spk14e ( ctx, handle ) bind(c, name='pepper_spk14e')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: handle  !! The handle of an SPK file open for writing.
      type(capi_context), pointer :: c_
      c_ => context_of(ctx)
      call c_%spk14e(handle)
      c_pepper_spk14e = status_of(c_)
   end function c_pepper_spk14e

   !> C interface of `spk_coverage`: The coverage of an object in an SPK file (PEPPER; [[spkcov]] without a window cell).
   integer(c_int) function c_pepper_spk_coverage ( ctx, file, body, intervals, intervals_rows, &
         intervals_cols ) bind(c, name='pepper_spk_coverage')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the SPK file
      integer(c_int), value :: body  !! the NAIF ID code of the object
      type(c_ptr), intent(out) :: intervals  !! the coverage, shape (2, n) (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: intervals_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: intervals_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      real(wp), allocatable :: f_intervals(:,:)
      integer(c_int) :: intervals_total
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_%spk_coverage(f_file, body, f_intervals)
      if (.not. allocated(f_intervals)) allocate (f_intervals(0, 0))
      call set_real_result(c_, 1, reshape(f_intervals, [size(f_intervals)]), intervals, intervals_total)
      intervals_rows = int(size(f_intervals, 2), c_int)
      intervals_cols = int(size(f_intervals, 1), c_int)
      c_pepper_spk_coverage = status_of(c_)
   end function c_pepper_spk_coverage

   !> C interface of `spk_objects`: The objects of an SPK file (PEPPER; [[spkobj]] without a set cell): their ID codes, sorted, without duplicates.
   integer(c_int) function c_pepper_spk_objects ( ctx, file, ids, ids_n ) bind(c, name='pepper_spk_objects')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: file(*)  !! the SPK file
      type(c_ptr), intent(out) :: ids  !! the ID codes (size 0 after an error) (in the context)
      integer(c_int), intent(out) :: ids_n  !! its size
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_file
      integer(ip), allocatable :: f_ids(:)
      c_ => context_of(ctx)
      call c_to_f(file, f_file)
      call c_%spk_objects(f_file, f_ids)
      if (.not. allocated(f_ids)) allocate (f_ids(0))
      call set_int_result(c_, 1, f_ids, ids, ids_n)
      c_pepper_spk_objects = status_of(c_)
   end function c_pepper_spk_objects

   !> C interface of `spkacs`: Return the state (position and velocity) of a target body relative to an observer, optionally corrected for light time and stellar aberration, expressed relative to an inertial reference frame.
   integer(c_int) function c_pepper_spkacs ( ctx, targ, et, ref, abcorr, obs, starg, lt, dlt ) bind(c, &
         name='pepper_spkacs')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: targ  !! Target body.
      real(c_double), value :: et  !! Observer epoch.
      character(kind=c_char), intent(in) :: ref(*)  !! Inertial reference frame of output state.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration correction flag.
      integer(c_int), value :: obs  !! Observer.
      real(c_double), intent(out) :: starg(6)  !! State of target.
      real(c_double), intent(out) :: lt  !! One way light time between observer and target.
      real(c_double), intent(out) :: dlt  !! Derivative of light time with respect to time.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_ref
      character(:), allocatable :: f_abcorr
      c_ => context_of(ctx)
      call c_to_f(ref, f_ref)
      call c_to_f(abcorr, f_abcorr)
      call c_%spkacs(targ, et, f_ref, f_abcorr, obs, starg, lt, dlt)
      c_pepper_spkacs = status_of(c_)
   end function c_pepper_spkacs

