   !> C interface of `spkcpo`: Return the state of a specified target relative to an "observer," where the observer has constant position in a specified reference frame.
   integer(c_int) function c_pepper_spkcpo ( ctx, target, et, outref, refloc, abcorr, obspos, obsctr, obsref, state, &
         lt ) bind(c, name='pepper_spkcpo')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: target(*)  !! Name of target ephemeris object.
      real(c_double), value :: et  !! Observation epoch.
      character(kind=c_char), intent(in) :: outref(*)  !! Reference frame of output state.
      character(kind=c_char), intent(in) :: refloc(*)  !! Output reference frame evaluation locus.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration correction.
      real(c_double), intent(in) :: obspos(3)  !! Observer position relative to center of motion.
      character(kind=c_char), intent(in) :: obsctr(*)  !! Center of motion of observer.
      character(kind=c_char), intent(in) :: obsref(*)  !! Frame of observer position.
      real(c_double), intent(out) :: state(6)  !! State of target with respect to observer.
      real(c_double), intent(out) :: lt  !! One way light time between target and observer.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_target
      character(:), allocatable :: f_outref
      character(:), allocatable :: f_refloc
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_obsctr
      character(:), allocatable :: f_obsref
      c_ => context_of(ctx)
      call c_to_f(target, f_target)
      call c_to_f(outref, f_outref)
      call c_to_f(refloc, f_refloc)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(obsctr, f_obsctr)
      call c_to_f(obsref, f_obsref)
      call c_%spkcpo(f_target, et, f_outref, f_refloc, f_abcorr, obspos, f_obsctr, f_obsref, state, lt)
      c_pepper_spkcpo = status_of(c_)
   end function c_pepper_spkcpo

   !> C interface of `spkcpt`: Return the state, relative to a specified observer, of a target having constant position in a specified reference frame.
   integer(c_int) function c_pepper_spkcpt ( ctx, trgpos, trgctr, trgref, et, outref, refloc, abcorr, obsrvr, state, &
         lt ) bind(c, name='pepper_spkcpt')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), intent(in) :: trgpos(3)  !! Target position relative to center of motion.
      character(kind=c_char), intent(in) :: trgctr(*)  !! Center of motion of target.
      character(kind=c_char), intent(in) :: trgref(*)  !! Frame of target position.
      real(c_double), value :: et  !! Observation epoch.
      character(kind=c_char), intent(in) :: outref(*)  !! Reference frame of output state.
      character(kind=c_char), intent(in) :: refloc(*)  !! Output reference frame evaluation locus.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration correction.
      character(kind=c_char), intent(in) :: obsrvr(*)  !! Name of observing ephemeris object.
      real(c_double), intent(out) :: state(6)  !! State of target with respect to observer.
      real(c_double), intent(out) :: lt  !! One way light time between target and observer.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_trgctr
      character(:), allocatable :: f_trgref
      character(:), allocatable :: f_outref
      character(:), allocatable :: f_refloc
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_obsrvr
      c_ => context_of(ctx)
      call c_to_f(trgctr, f_trgctr)
      call c_to_f(trgref, f_trgref)
      call c_to_f(outref, f_outref)
      call c_to_f(refloc, f_refloc)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(obsrvr, f_obsrvr)
      call c_%spkcpt(trgpos, f_trgctr, f_trgref, et, f_outref, f_refloc, f_abcorr, f_obsrvr, state, lt)
      c_pepper_spkcpt = status_of(c_)
   end function c_pepper_spkcpt

   !> C interface of `spkcvo`: Return the state of a specified target relative to an "observer," where the observer has constant velocity in a specified reference frame.
