   !> C interface of `srfc2s`: Translate a surface ID code, together with a body ID code, to the corresponding surface name.
   integer(c_int) function c_pepper_srfc2s ( ctx, code, bodyid, srfstr_size, srfstr, isname ) bind(c, &
         name='pepper_srfc2s')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: code  !! Integer surface ID code to translate to a string.
      integer(c_int), value :: bodyid  !! ID code of body associated with surface.
      integer(c_int), value :: srfstr_size  !! the size of srfstr (with the NUL)
      character(kind=c_char), intent(out) :: srfstr(*)  !! String corresponding to surface ID code.
      integer(c_int), intent(out) :: isname  !! Logical flag indicating output is a surface name.
      type(capi_context), pointer :: c_
      character(len=max(srfstr_size - 1, 1)) :: f_srfstr
      logical :: f_isname
      c_ => context_of(ctx)
      f_srfstr = ' '
      call c_%srfc2s(code, bodyid, f_srfstr, f_isname)
      call f_to_c(f_srfstr, srfstr_size, srfstr)
      isname = merge(1_c_int, 0_c_int, f_isname)
      c_pepper_srfc2s = status_of(c_)
   end function c_pepper_srfc2s

   !> C interface of `srfcss`: Translate a surface ID code, together with a body string, to the corresponding surface name.
   integer(c_int) function c_pepper_srfcss ( ctx, code, bodstr, srfstr_size, srfstr, isname ) bind(c, &
         name='pepper_srfcss')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: code  !! Integer surface ID code to translate to a string.
      character(kind=c_char), intent(in) :: bodstr(*)  !! Name or ID of body associated with surface.
      integer(c_int), value :: srfstr_size  !! the size of srfstr (with the NUL)
      character(kind=c_char), intent(out) :: srfstr(*)  !! String corresponding to surface ID code.
      integer(c_int), intent(out) :: isname  !! Flag indicating whether output is a surface name.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_bodstr
      character(len=max(srfstr_size - 1, 1)) :: f_srfstr
      logical :: f_isname
      c_ => context_of(ctx)
      call c_to_f(bodstr, f_bodstr)
      f_srfstr = ' '
