   !> C interface of `tangpt`: Compute, for a given observer, ray emanating from the observer, and target, the "tangent point": the point on the ray nearest to the target's surface.
   integer(c_int) function c_pepper_tangpt ( ctx, method, target, et, fixref, abcorr, corloc, obsrvr, dref, dvec, &
         tanpt, alt, range, srfpt, trgepc, srfvec ) bind(c, name='pepper_tangpt')
      type(c_ptr), value :: ctx  !! the context
