      character(kind=c_char), intent(in) :: fixref(*)  !! Body-fixed, body-centered target body frame.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration correction.
      character(kind=c_char), intent(in) :: corloc(*)  !! Aberration correction locus: 'TANGENT POINT' or 'SURFACE POINT'.
      character(kind=c_char), intent(in) :: obsrvr(*)  !! Name of observing body.
      character(kind=c_char), intent(in) :: dref(*)  !! Reference frame of ray direction vector.
      real(c_double), intent(in) :: dvec(3)  !! Ray direction vector.
      real(c_double), intent(out) :: tanpt(3)  !! "Tangent point": point on ray nearest to surface.
      real(c_double), intent(out) :: alt  !! Altitude of tangent point above surface.
      real(c_double), intent(out) :: range  !! Distance of tangent point from observer.
      real(c_double), intent(out) :: srfpt(3)  !! Point on surface nearest to tangent point.
      real(c_double), intent(out) :: trgepc  !! Epoch associated with correction locus.
      real(c_double), intent(out) :: srfvec(3)  !! Vector from observer to surface point SRFPT.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_method
      character(:), allocatable :: f_target
      character(:), allocatable :: f_fixref
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_corloc
      character(:), allocatable :: f_obsrvr
