      c_ => context_of(ctx)
      call c_to_f(method, f_method)
      call c_to_f(target, f_target)
      call c_to_f(fixref, f_fixref)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(corloc, f_corloc)
      call c_to_f(obsrvr, f_obsrvr)
      call c_to_f(dref, f_dref)
      call c_%tangpt(f_method, f_target, et, f_fixref, f_abcorr, f_corloc, f_obsrvr, f_dref, dvec, tanpt, alt, range, &
               srfpt, trgepc, srfvec)
      c_pepper_tangpt = status_of(c_)
   end function c_pepper_tangpt

   !> C interface of `tchckd`: Determine whether component checking is enabled for time strings.
   integer(c_int) function c_pepper_tchckd ( ctx, type_size, type ) bind(c, name='pepper_tchckd')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: type_size  !! the size of type (with the NUL)
      character(kind=c_char), intent(out) :: type(*)  !! Answer to the question: "Is checking enabled?"
      type(capi_context), pointer :: c_
      character(len=max(type_size - 1, 1)) :: f_type
      c_ => context_of(ctx)
      f_type = ' '
      call c_%tchckd(f_type)
      call f_to_c(f_type, type_size, type)
      c_pepper_tchckd = status_of(c_)
   end function c_pepper_tchckd

   !> C interface of `tcheck`: Determine whether the components of a time vector are in the "usual" range for the components, if component checking is enabled.
   integer(c_int) function c_pepper_tcheck ( ctx, tvec, type, mods, modify_n, modify_width, modify, ok, error_size, &
         error ) bind(c, name='pepper_tcheck')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), intent(in) :: tvec(*)  !! A vector of time components
      character(kind=c_char), intent(in) :: type(*)  !! The type of time vector.
      integer(c_int), value :: mods  !! A logical indicating the presence of modifiers
      integer(c_int), value :: modify_n  !! the number of strings in modify
      integer(c_int), value :: modify_width  !! the width of each string in modify
      character(kind=c_char), intent(in) :: modify(*)  !! The values of the modifiers
      integer(c_int), intent(out) :: ok  !! Indicates success or failure of component checks.
      integer(c_int), value :: error_size  !! the size of error (with the NUL)
      character(kind=c_char), intent(out) :: error(*)  !! Diagnostic message if .NOT. OK.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_type
      character(:), allocatable :: f_modify(:)
      logical :: f_ok
      character(len=max(error_size - 1, 1)) :: f_error
      c_ => context_of(ctx)
      call c_to_f(type, f_type)
      call c_to_f_array(modify, modify_n, modify_width, f_modify)
      f_error = ' '
      call c_%tcheck(tvec, f_type, (mods /= 0), f_modify, f_ok, f_error)
      ok = merge(1_c_int, 0_c_int, f_ok)
      call f_to_c(f_error, error_size, error)
      c_pepper_tcheck = status_of(c_)
   end function c_pepper_tcheck

   !> C interface of `terminator_points`: Terminator points on a target body, without a limit on their number (PEPPER; [[termpt]] without MAXN).
   integer(c_int) function c_pepper_terminator_points ( ctx, method, ilusrc, target, et, fixref, abcorr, corloc, &
         obsrvr, refvec, rolstp, ncuts, schstp, soltol, npts, npts_n, points, points_rows, points_cols, epochs, &
         epochs_n, trmvcs, trmvcs_rows, trmvcs_cols ) bind(c, name='pepper_terminator_points')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: method(*)  !! the computation method, as for [[termpt]]
      character(kind=c_char), intent(in) :: ilusrc(*)  !! the illumination source
      character(kind=c_char), intent(in) :: target(*)  !! the name of the target body
      real(c_double), value :: et  !! the epoch (TDB seconds past J2000)
      character(kind=c_char), intent(in) :: fixref(*)  !! the body-fixed, body-centered target body frame
      character(kind=c_char), intent(in) :: abcorr(*)  !! the aberration correction
      character(kind=c_char), intent(in) :: corloc(*)  !! the aberration correction locus
      character(kind=c_char), intent(in) :: obsrvr(*)  !! the name of the observing body
      real(c_double), intent(in) :: refvec(3)  !! the reference vector for the cutting half-planes
      real(c_double), value :: rolstp  !! the roll angular step between the cutting half-planes
      integer(c_int), value :: ncuts  !! the number of cutting half-planes
      real(c_double), value :: schstp  !! the angular step size for searching (DSK shapes)
      real(c_double), value :: soltol  !! the solution convergence tolerance (DSK shapes)
      type(c_ptr), intent(out) :: npts  !! the number of points of each cut (size 0 after an error) (in the context)
      integer(c_int), intent(out) :: npts_n  !! its size
      type(c_ptr), intent(out) :: points  !! the terminator points, shape (3, n) (n = 0 after an error) (in the context)
      integer(c_int), intent(out) :: points_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: points_cols  !! its number of columns (Fortran: rows)
      type(c_ptr), intent(out) :: epochs  !! the epochs of the points (in the context)
      integer(c_int), intent(out) :: epochs_n  !! its size
      type(c_ptr), intent(out) :: trmvcs  !! the vectors from the observer to the points, shape (3, n) (in the context)
      integer(c_int), intent(out) :: trmvcs_rows  !! its number of rows (Fortran: columns)
      integer(c_int), intent(out) :: trmvcs_cols  !! its number of columns (Fortran: rows)
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_method
      character(:), allocatable :: f_ilusrc
      character(:), allocatable :: f_target
      character(:), allocatable :: f_fixref
      character(:), allocatable :: f_abcorr
      character(:), allocatable :: f_corloc
      character(:), allocatable :: f_obsrvr
      integer(ip), allocatable :: f_npts(:)
      real(wp), allocatable :: f_points(:,:)
      integer(c_int) :: points_total
      real(wp), allocatable :: f_epochs(:)
      real(wp), allocatable :: f_trmvcs(:,:)
      integer(c_int) :: trmvcs_total
      c_ => context_of(ctx)
      call c_to_f(method, f_method)
      call c_to_f(ilusrc, f_ilusrc)
      call c_to_f(target, f_target)
      call c_to_f(fixref, f_fixref)
      call c_to_f(abcorr, f_abcorr)
      call c_to_f(corloc, f_corloc)
      call c_to_f(obsrvr, f_obsrvr)
      call c_%terminator_points(f_method, f_ilusrc, f_target, et, f_fixref, f_abcorr, f_corloc, f_obsrvr, refvec, rolstp, &
               ncuts, schstp, soltol, f_npts, f_points, f_epochs, f_trmvcs)
      if (.not. allocated(f_npts)) allocate (f_npts(0))
      call set_int_result(c_, 1, f_npts, npts, npts_n)
      if (.not. allocated(f_points)) allocate (f_points(0, 0))
      call set_real_result(c_, 1, reshape(f_points, [size(f_points)]), points, points_total)
      points_rows = int(size(f_points, 2), c_int)
      points_cols = int(size(f_points, 1), c_int)
      if (.not. allocated(f_epochs)) allocate (f_epochs(0))
      call set_real_result(c_, 2, f_epochs, epochs, epochs_n)
      if (.not. allocated(f_trmvcs)) allocate (f_trmvcs(0, 0))
      call set_real_result(c_, 3, reshape(f_trmvcs, [size(f_trmvcs)]), trmvcs, trmvcs_total)
      trmvcs_rows = int(size(f_trmvcs, 2), c_int)
      trmvcs_cols = int(size(f_trmvcs, 1), c_int)
      c_pepper_terminator_points = status_of(c_)
   end function c_pepper_terminator_points

