   !> C interface of `tisbod`: Return a 6x6 matrix that transforms states in inertial coordinates to states in body-equator-and-prime-meridian coordinates.
   integer(c_int) function c_pepper_tisbod ( ctx, ref, body, et, tsipm ) bind(c, name='pepper_tisbod')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: ref(*)  !! ID of inertial reference frame to transform from
      integer(c_int), value :: body  !! ID code of body
      real(c_double), value :: et  !! Epoch of transformation
      real(c_double), intent(out) :: tsipm(6,6)  !! Transformation (state), inertial to prime meridian
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_ref
      c_ => context_of(ctx)
      call c_to_f(ref, f_ref)
      call c_%tisbod(f_ref, body, et, tsipm)
      c_pepper_tisbod = status_of(c_)
   end function c_pepper_tisbod

   !> C interface of `tkfram`: Find the position rotation matrix from a Text Kernel (TK) frame with the specified frame class ID to its base frame.
   integer(c_int) function c_pepper_tkfram ( ctx, frcode, rot, frame, found ) bind(c, name='pepper_tkfram')
      type(c_ptr), value :: ctx  !! the context
      integer(c_int), value :: frcode  !! Frame class ID of a TK frame.
      real(c_double), intent(out) :: rot(3,3)  !! Rotation matrix from TK frame to frame FRAME.
      integer(c_int), intent(out) :: frame  !! Frame ID of the base reference.
