   !> C interface of `tparse`: Parse a time string and return seconds past the J2000 epoch on a formal calendar.
   integer(c_int) function c_pepper_tparse ( ctx, string, sp2000, errmsg_size, errmsg ) bind(c, name='pepper_tparse')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: string(*)  !! Input time string, UTC.
      real(c_double), intent(out) :: sp2000  !! Equivalent UTC seconds past J2000.
      integer(c_int), value :: errmsg_size  !! the size of errmsg (with the NUL)
      character(kind=c_char), intent(out) :: errmsg(*)  !! Descriptive error message.
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_string
      character(len=max(errmsg_size - 1, 1)) :: f_errmsg
      c_ => context_of(ctx)
      call c_to_f(string, f_string)
      f_errmsg = ' '
      call c_%tparse(f_string, sp2000, f_errmsg)
      call f_to_c(f_errmsg, errmsg_size, errmsg)
      c_pepper_tparse = status_of(c_)
   end function c_pepper_tparse

   !> C interface of `tpartv`: Parse the components of a time string and return a vector of the components of that string.
   integer(c_int) function c_pepper_tpartv ( ctx, string, tvec, ntvec, type_size, type, modify_n, modify_width, &
         modify, mods, yabbrv, succes, pictur_size, pictur, error_size, error ) bind(c, name='pepper_tpartv')
      integer(c_int), value :: modify_n  !! the number of strings modify holds
      integer(c_int), value :: modify_width  !! the size of each (with the NUL)
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: string(*)  !! A string to be parsed as a time
      real(c_double), intent(out) :: tvec(*)  !! A vector giving the components of the time.
      integer(c_int), intent(out) :: ntvec  !! The number of components supplied for TVEC
      integer(c_int), value :: type_size  !! the size of type (with the NUL)
      character(kind=c_char), intent(out) :: type(*)  !! The type of the "time vector" TVEC
      character(kind=c_char), intent(out) :: modify(modify_n * modify_width)  !! A list of modifiers present in STRING.
      integer(c_int), intent(out) :: mods  !! A logical indicating the presence of a modifier
      integer(c_int), intent(out) :: yabbrv  !! A logical indicating that a year was abbreviated
      integer(c_int), intent(out) :: succes  !! A logical indicating whether STRING was parsed.
      integer(c_int), value :: pictur_size  !! the size of pictur (with the NUL)
      character(kind=c_char), intent(out) :: pictur(*)  !! A time format picture associated with STRING
      integer(c_int), value :: error_size  !! the size of error (with the NUL)
      character(kind=c_char), intent(out) :: error(*)  !! A diagnostic message if STRING couldn't be parsed
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_string
      character(len=max(type_size - 1, 1)) :: f_type
      character(len=max(modify_width - 1, 1)) :: f_modify(max(modify_n, 1))
      integer :: i_modify
      logical :: f_mods
      logical :: f_yabbrv
      logical :: f_succes
      character(len=max(pictur_size - 1, 1)) :: f_pictur
      character(len=max(error_size - 1, 1)) :: f_error
      c_ => context_of(ctx)
      call c_to_f(string, f_string)
      f_type = ' '
      f_modify = ' '
      f_pictur = ' '
      f_error = ' '
      call c_%tpartv(f_string, tvec, ntvec, f_type, f_modify, f_mods, f_yabbrv, f_succes, f_pictur, f_error)
      call f_to_c(f_type, type_size, type)
      do i_modify = 1, modify_n
         call f_to_c(f_modify(i_modify), modify_width, modify((i_modify - 1) * modify_width + 1:i_modify * modify_width))
      end do
      mods = merge(1_c_int, 0_c_int, f_mods)
      yabbrv = merge(1_c_int, 0_c_int, f_yabbrv)
      succes = merge(1_c_int, 0_c_int, f_succes)
      call f_to_c(f_pictur, pictur_size, pictur)
      call f_to_c(f_error, error_size, error)
      c_pepper_tpartv = status_of(c_)
   end function c_pepper_tpartv

   !> C interface of `tpictr`: Create a time format picture suitable for use by the routine [[timout]] from a given sample time string.
   integer(c_int) function c_pepper_tpictr ( ctx, sample, pictur_size, pictur, ok, errmsg_size, errmsg ) bind(c, &
         name='pepper_tpictr')
      type(c_ptr), value :: ctx  !! the context
      character(kind=c_char), intent(in) :: sample(*)  !! is a sample date time string
      integer(c_int), value :: pictur_size  !! the size of pictur (with the NUL)
      character(kind=c_char), intent(out) :: pictur(*)  !! is a format picture that describes SAMPLE
      integer(c_int), intent(out) :: ok  !! indicates success or failure to parse SAMPLE
      integer(c_int), value :: errmsg_size  !! the size of errmsg (with the NUL)
      character(kind=c_char), intent(out) :: errmsg(*)  !! a diagnostic returned if SAMPLE cannot be parsed
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_sample
      character(len=max(pictur_size - 1, 1)) :: f_pictur
      logical :: f_ok
      character(len=max(errmsg_size - 1, 1)) :: f_errmsg
      c_ => context_of(ctx)
      call c_to_f(sample, f_sample)
      f_pictur = ' '
      f_errmsg = ' '
      call c_%tpictr(f_sample, f_pictur, f_ok, f_errmsg)
      call f_to_c(f_pictur, pictur_size, pictur)
      ok = merge(1_c_int, 0_c_int, f_ok)
      call f_to_c(f_errmsg, errmsg_size, errmsg)
      c_pepper_tpictr = status_of(c_)
   end function c_pepper_tpictr

   !> C interface of `trgsep`: Compute the angular separation in radians between two spherical or point objects.
   integer(c_int) function c_pepper_trgsep ( ctx, et, targ1, shape1, frame1, targ2, shape2, frame2, obsrvr, abcorr, &
         fresult ) bind(c, name='pepper_trgsep')
      type(c_ptr), value :: ctx  !! the context
      real(c_double), value :: et  !! Ephemeris seconds past J2000 TDB.
      character(kind=c_char), intent(in) :: targ1(*)  !! First target body name.
      character(kind=c_char), intent(in) :: shape1(*)  !! First target body shape.
      character(kind=c_char), intent(in) :: frame1(*)  !! Reference frame of first target.
      character(kind=c_char), intent(in) :: targ2(*)  !! Second target body name.
      character(kind=c_char), intent(in) :: shape2(*)  !! First target body shape.
      character(kind=c_char), intent(in) :: frame2(*)  !! Reference frame of second target.
      character(kind=c_char), intent(in) :: obsrvr(*)  !! Observing body name.
      character(kind=c_char), intent(in) :: abcorr(*)  !! Aberration corrections flag.
      real(c_double), intent(out) :: fresult  !! the result
      type(capi_context), pointer :: c_
      character(:), allocatable :: f_targ1
      character(:), allocatable :: f_shape1
      character(:), allocatable :: f_frame1
      character(:), allocatable :: f_targ2
      character(:), allocatable :: f_shape2
      character(:), allocatable :: f_frame2
      character(:), allocatable :: f_obsrvr
      character(:), allocatable :: f_abcorr
      real(wp) :: f_fresult
      c_ => context_of(ctx)
      call c_to_f(targ1, f_targ1)
      call c_to_f(shape1, f_shape1)
      call c_to_f(frame1, f_frame1)
      call c_to_f(targ2, f_targ2)
      call c_to_f(shape2, f_shape2)
      call c_to_f(frame2, f_frame2)
      call c_to_f(obsrvr, f_obsrvr)
      call c_to_f(abcorr, f_abcorr)
      f_fresult = c_%trgsep(et, f_targ1, f_shape1, f_frame1, f_targ2, f_shape2, f_frame2, f_obsrvr, f_abcorr)
      fresult = f_fresult
      c_pepper_trgsep = status_of(c_)
   end function c_pepper_trgsep

