   !> C interface of `nextwd`: Return the next word in a given character string, and left justify the rest of the string.
   integer(c_int) function c_pepper_nextwd ( string, next_size, next, rest_size, rest ) bind(c, name='pepper_nextwd')
      character(kind=c_char), intent(in) :: string(*)  !! Input character string.
      integer(c_int), value :: next_size  !! the size of next (with the NUL)
      character(kind=c_char), intent(out) :: next(*)  !! The next word in the string.
      integer(c_int), value :: rest_size  !! the size of rest (with the NUL)
      character(kind=c_char), intent(out) :: rest(*)  !! The remaining part of STRING, left-justified.
      character(:), allocatable :: f_string
      character(len=max(next_size - 1, 1)) :: f_next
      character(len=max(rest_size - 1, 1)) :: f_rest
      call c_to_f(string, f_string)
      f_next = ' '
      f_rest = ' '
      call nextwd(f_string, f_next, f_rest)
      call f_to_c(f_next, next_size, next)
      call f_to_c(f_rest, rest_size, rest)
      c_pepper_nextwd = 0_c_int
   end function c_pepper_nextwd

