      f_next = ' '
      call nextwd_inplace(f_string, f_next)
      call f_to_c(f_string, string_size, string)
      call f_to_c(f_next, next_size, next)
      c_pepper_nextwd_inplace = 0_c_int
   end function c_pepper_nextwd_inplace

