   !> C interface of `parsqs`: Parse a quoted string token.
   integer(c_int) function c_pepper_parsqs ( string, qchar, value_size, value, length, error, errmsg_size, errmsg, &
         ptr ) bind(c, name='pepper_parsqs')
      character(kind=c_char), intent(in) :: string(*)  !! Quoted string to be parsed.
      character(kind=c_char), intent(in) :: qchar(*)  !! Quote delimiter character.
      integer(c_int), value :: value_size  !! the size of value (with the NUL)
      character(kind=c_char), intent(out) :: value(*)  !! Parsed string.
      integer(c_int), intent(out) :: length  !! Number of significant characters in VALUE.
      integer(c_int), intent(out) :: error  !! Logical error flag.
      integer(c_int), value :: errmsg_size  !! the size of errmsg (with the NUL)
      character(kind=c_char), intent(out) :: errmsg(*)  !! Message indicating whether errors have occurred.
      integer(c_int), intent(out) :: ptr  !! Position in string where an error occurred.
      character(:), allocatable :: f_string
      character(:), allocatable :: f_qchar
      character(len=max(value_size - 1, 1)) :: f_value
      logical :: f_error
      character(len=max(errmsg_size - 1, 1)) :: f_errmsg
      call c_to_f(string, f_string)
      call c_to_f(qchar, f_qchar)
      f_value = ' '
      f_errmsg = ' '
      call parsqs(f_string, f_qchar, f_value, length, f_error, f_errmsg, ptr)
      call f_to_c(f_value, value_size, value)
      error = merge(1_c_int, 0_c_int, f_error)
      call f_to_c(f_errmsg, errmsg_size, errmsg)
      c_pepper_parsqs = 0_c_int
   end function c_pepper_parsqs

