   !> C interface of `vsep`: Find the separation angle in radians between two double precision, 3-dimensional vectors.
   integer(c_int) function c_pepper_vsep ( v1, v2, fresult ) bind(c, name='pepper_vsep')
      real(c_double), intent(in) :: v1(3)  !! First vector.
      real(c_double), intent(in) :: v2(3)  !! Second vector.
      real(c_double), intent(out) :: fresult  !! the result
      real(wp) :: f_fresult
      f_fresult = vsep(v1, v2)
      fresult = f_fresult
      c_pepper_vsep = 0_c_int
   end function c_pepper_vsep

   !> C interface of `vsepg`: Find the separation angle in radians between two double precision vectors of arbitrary dimension.
   integer(c_int) function c_pepper_vsepg ( v1, v2, ndim, fresult ) bind(c, name='pepper_vsepg')
      real(c_double), intent(in) :: v1(*)  !! First vector.
      real(c_double), intent(in) :: v2(*)  !! Second vector.
      integer(c_int), value :: ndim  !! The number of elements in V1 and V2.
      real(c_double), intent(out) :: fresult  !! the result
      real(wp) :: f_fresult
      f_fresult = vsepg(v1, v2, ndim)
      fresult = f_fresult
      c_pepper_vsepg = 0_c_int
   end function c_pepper_vsepg

   !> C interface of `vsub`: Compute the difference between two double precision 3-dimensional vectors.
   integer(c_int) function c_pepper_vsub ( v1, v2, vout ) bind(c, name='pepper_vsub')
      real(c_double), intent(in) :: v1(3)  !! First vector (minuend).
      real(c_double), intent(in) :: v2(3)  !! Second vector (subtrahend).
      real(c_double), intent(out) :: vout(3)  !! Difference vector, V1 - V2.
      call vsub(v1, v2, vout)
      c_pepper_vsub = 0_c_int
   end function c_pepper_vsub

   !> C interface of `vsubg`: Compute the difference between two double precision vectors of arbitrary dimension.
   integer(c_int) function c_pepper_vsubg ( v1, v2, ndim, vout ) bind(c, name='pepper_vsubg')
      integer(c_int), value :: ndim  !! Dimension of V1, V2, and VOUT.
      real(c_double), intent(in) :: v1(ndim)  !! First vector (minuend).
      real(c_double), intent(in) :: v2(ndim)  !! Second vector (subtrahend).
      real(c_double), intent(out) :: vout(ndim)  !! Difference vector, V1 - V2.
      call vsubg(v1, v2, ndim, vout)
      c_pepper_vsubg = 0_c_int
   end function c_pepper_vsubg

   !> C interface of `vtmv`: Multiply the transpose of a 3-dimensional column vector, a 3x3 matrix, and a 3-dimensional column vector.
   integer(c_int) function c_pepper_vtmv ( v1, matrix, v2, fresult ) bind(c, name='pepper_vtmv')
      real(c_double), intent(in) :: v1(3)  !! 3-dimensional double precision column vector.
      real(c_double), intent(in) :: matrix(3,3)  !! 3x3 double precision matrix.
      real(c_double), intent(in) :: v2(3)  !! 3-dimensional double precision column vector.
      real(c_double), intent(out) :: fresult  !! the result
      real(wp) :: f_fresult
      f_fresult = vtmv(v1, matrix, v2)
      fresult = f_fresult
      c_pepper_vtmv = 0_c_int
   end function c_pepper_vtmv

   !> C interface of `vtmvg`: Multiply the transpose of a n-dimensional column vector, a nxm matrix, and a m-dimensional column vector.
   integer(c_int) function c_pepper_vtmvg ( v1, matrix, v2, nrow, ncol, fresult ) bind(c, name='pepper_vtmvg')
      integer(c_int), value :: nrow  !! Number of rows in MATRIX (number of rows in V1.)
      integer(c_int), value :: ncol  !! Number of columns in MATRIX (number of rows in V2.)
      real(c_double), intent(in) :: v1(nrow)  !! N-dimensional double precision column
      real(c_double), intent(in) :: matrix(nrow,ncol)  !! NxM double precision matrix.
      real(c_double), intent(in) :: v2(ncol)  !! M-dimensional double precision column
      real(c_double), intent(out) :: fresult  !! the result
      real(wp) :: f_fresult
      f_fresult = vtmvg(v1, matrix, v2, nrow, ncol)
      fresult = f_fresult
      c_pepper_vtmvg = 0_c_int
   end function c_pepper_vtmvg

   !> C interface of `vupack`: Unpack three scalar components from a vector.
   integer(c_int) function c_pepper_vupack ( v, x, y, z ) bind(c, name='pepper_vupack')
      real(c_double), intent(in) :: v(3)  !! Input 3-dimensional vector.
      real(c_double), intent(out) :: x  !! Scalar components of the vector.
      real(c_double), intent(out) :: y  !! Scalar components of the vector.
      real(c_double), intent(out) :: z  !! Scalar components of the vector.
      call vupack(v, x, y, z)
      c_pepper_vupack = 0_c_int
   end function c_pepper_vupack

   !> C interface of `vzero`: Indicate whether a 3-vector is the zero vector.
   integer(c_int) function c_pepper_vzero ( v, fresult ) bind(c, name='pepper_vzero')
      real(c_double), intent(in) :: v(3)  !! Vector to be tested.
      integer(c_int), intent(out) :: fresult  !! the result
      logical :: f_fresult
      f_fresult = vzero(v)
      fresult = merge(1_c_int, 0_c_int, f_fresult)
      c_pepper_vzero = 0_c_int
   end function c_pepper_vzero

   !> C interface of `vzerog`: Indicate whether an n-dimensional vector is the zero vector.
   integer(c_int) function c_pepper_vzerog ( v, ndim, fresult ) bind(c, name='pepper_vzerog')
      real(c_double), intent(in) :: v(*)  !! Vector to be tested.
      integer(c_int), value :: ndim  !! Dimension of V.
      integer(c_int), intent(out) :: fresult  !! the result
      logical :: f_fresult
      f_fresult = vzerog(v, ndim)
      fresult = merge(1_c_int, 0_c_int, f_fresult)
      c_pepper_vzerog = 0_c_int
   end function c_pepper_vzerog

   !> C interface of `wdcnt`: Return the number of words in a string.
   integer(c_int) function c_pepper_wdcnt ( string, fresult ) bind(c, name='pepper_wdcnt')
      character(kind=c_char), intent(in) :: string(*)  !! Input character string.
      integer(c_int), intent(out) :: fresult  !! the result
      character(:), allocatable :: f_string
      integer(ip) :: f_fresult
      call c_to_f(string, f_string)
      f_fresult = wdcnt(f_string)
      fresult = f_fresult
      c_pepper_wdcnt = 0_c_int
   end function c_pepper_wdcnt

   !> C interface of `wdindx`: Find the index of a word within a string.
   integer(c_int) function c_pepper_wdindx ( string, word, fresult ) bind(c, name='pepper_wdindx')
      character(kind=c_char), intent(in) :: string(*)  !! String of characters, potentially containing words
      character(kind=c_char), intent(in) :: word(*)  !! A string of consecutive printable letters.
      integer(c_int), intent(out) :: fresult  !! the result
      character(:), allocatable :: f_string
      character(:), allocatable :: f_word
      integer(ip) :: f_fresult
      call c_to_f(string, f_string)
      call c_to_f(word, f_word)
      f_fresult = wdindx(f_string, f_word)
      fresult = f_fresult
      c_pepper_wdindx = 0_c_int
   end function c_pepper_wdindx

   !> C interface of `xf2rav`: Determine the rotation matrix and angular velocity of the rotation from a state transformation matrix.
   integer(c_int) function c_pepper_xf2rav ( xform, rot, av ) bind(c, name='pepper_xf2rav')
      real(c_double), intent(in) :: xform(6,6)  !! is a state transformation matrix.
      real(c_double), intent(out) :: rot(3,3)  !! is the rotation associated with XFORM.
      real(c_double), intent(out) :: av(3)  !! is the angular velocity associated with XFORM.
      call xf2rav(xform, rot, av)
      c_pepper_xf2rav = 0_c_int
   end function c_pepper_xf2rav

   !> C interface of `xpose`: Transpose a 3x3 matrix.
   integer(c_int) function c_pepper_xpose ( m1, mout ) bind(c, name='pepper_xpose')
      real(c_double), intent(in) :: m1(3,3)  !! 3x3 matrix to be transposed.
      real(c_double), intent(out) :: mout(3,3)  !! Transpose of M1.
      call xpose(m1, mout)
      c_pepper_xpose = 0_c_int
   end function c_pepper_xpose

   !> C interface of `xpsgip`: Transpose a matrix of arbitrary size and shape in place.
   integer(c_int) function c_pepper_xpsgip ( nrow, ncol, matrix ) bind(c, name='pepper_xpsgip')
      integer(c_int), value :: nrow  !! Number of rows of input matrix.
      integer(c_int), value :: ncol  !! Number of columns of input matrix.
      real(c_double), intent(inout) :: matrix(*)  !! Matrix to be transposed/transposed matrix.
      call xpsgip(nrow, ncol, matrix)
      c_pepper_xpsgip = 0_c_int
   end function c_pepper_xpsgip

end module pepper_capi
